type Tab = "MARKET"|"CROWD"|"DOSSIER"|"NEWS"|"SMART MONEY"|"SIGNAL TAPE"|"DISCOVERY LANE"|"THEORIES"|"ENGINE HITS"|"WATCHLIST"|"ALERTS"|"JOURNAL";
