const money = (n:number|null|undefined,c="USD") => n==null?"—":new Intl.NumberFormat(undefined,{style:"currency",currency:c,maximumFractionDigits:n>=100?2:4}).format(n);
const quoteMoney = (n:number|null|undefined,c:string|null|undefined) => n==null?"—":c?money(n,c):`${num(n)} · currency unavailable`;
const num = (n:number|null|undefined,d=2) => n==null?"—":new Intl.NumberFormat(undefined,{maximumFractionDigits:d,notation:Math.abs(n)>=1_000_000?"compact":"standard"}).format(n);
const pct = (n:number|null|undefined) => n==null?"—":`${n>=0?"+":""}${num(n)}%`;
const dateLabel = (d:string) => { const parts=d.split("-").map(Number); const y=parts[0],m=parts[1],day=parts[2]; return y&&m&&day?new Intl.DateTimeFormat(undefined,{month:"short",day:"numeric"}).format(new Date(y,m-1,day)):d; };
const asOfLabel = (iso:string|null|undefined) => iso&&Number.isFinite(Date.parse(iso))?new Date(iso).toLocaleString():"timestamp unavailable";
const isStale = (iso:string|null|undefined) => !iso||!Number.isFinite(Date.parse(iso))||Date.now()-Date.parse(iso)>36*60*60*1000;
// Radar freshness grouping (2026-10-18): reuses the existing 36h isStale semantics.
// Unknown timestamps stay "unknown" — they are NOT folded into "stale".
const radarFreshnessGroup = (sourceAsOf:string|null|undefined):"fresh"|"stale"|"unknown" => { if(!sourceAsOf||!Number.isFinite(Date.parse(sourceAsOf))) return "unknown"; return isStale(sourceAsOf)?"stale":"fresh"; };
// Expanded-row badge uses the SAME classification as the group headers.
const radarBadge = (sourceAsOf:string|null|undefined):{cls:string;label:string} => { const g=radarFreshnessGroup(sourceAsOf); return g==="fresh"?{cls:"fresh",label:"FRESH"}:g==="stale"?{cls:"stale",label:"STALE"}:{cls:"unknown",label:"TIMESTAMP UNKNOWN"}; };
const sessionDateKey = (iso:string|null|undefined) => { const match=iso?.match(/^(\d{4}-\d{2}-\d{2})/); return match?.[1]??null; };
const regimeFreshness = (regimeAsOf:string|null|undefined,indexAsOf:Array<string|null|undefined>) => { const regimeSession=sessionDateKey(regimeAsOf); const currentSession=indexAsOf.map(sessionDateKey).filter((value):value is string=>value!=null).sort().at(-1)??null; return { stale:regimeSession==null||currentSession==null||regimeSession<currentSession, currentSession }; };
const directionLabel = (direction:"long"|"short"|"mixed") => direction==="long"?"LONG / bullish":direction==="short"?"SHORT / bearish":"MIXED / no directional edge";
type TrackerSignal = ApiResponse<typeof api,"getSignalTracker">["signals"][number];
type MonitoringOutcome = "HIT"|"MISSED"|"EXPIRED";
type MonitoringClosure = NonNullable<TrackerSignal["monitoringClosure"]>;
const markOutcome = (direction:"long"|"short",mark:number|null|undefined,invalidation:number|null|undefined,target1:number|null|undefined):MonitoringOutcome|null => {
 if(mark==null)return null;
 if(invalidation!=null&&(direction==="long"?mark<=invalidation:mark>=invalidation))return "MISSED";
 if(target1!=null&&(direction==="long"?mark>=target1:mark<=target1))return "HIT";
 return null;
};
const ratingBand = (score:number) => Math.abs(score)>=80?"80–100 alignment":Math.abs(score)>=65?"65–79 alignment":"0–64 alignment";
const OPEN_SIGNAL_CACHE_KEY = "equity-terminal-open-signals-v1";
const MARKET_BRIEF_CACHE_KEY = "equity-terminal-market-brief-v1";
function readOpenSignalCache(): OpenSignalSummaryLoad|null {
 try {
  const parsed=JSON.parse(localStorage.getItem(OPEN_SIGNAL_CACHE_KEY)??"null") as {summary?:OpenSignalSummary;cachedAt?:string}|null;
  return parsed?.summary&&typeof parsed.summary.generatedAt==="string"&&typeof parsed.cachedAt==="string"?{summary:parsed.summary,source:"cached",cachedAt:parsed.cachedAt,fallbackReason:null}:null;
 } catch { return null; }
}
function readMarketBriefCache(): MarketBriefLoad|null {
 try {
  const parsed=JSON.parse(localStorage.getItem(MARKET_BRIEF_CACHE_KEY)??"null") as {brief?:MarketBrief;cachedAt?:string}|null;
  return parsed?.brief&&typeof parsed.brief.generatedAt==="string"&&typeof parsed.cachedAt==="string"?{brief:parsed.brief,source:"cached",cachedAt:parsed.cachedAt,fallbackReason:null}:null;
 } catch { return null; }
}
// The isolated malfunction capture measured a 15.7 s cold artifact launch. The
// old 3.75 s client race expired before the server action could answer, even
// though the database read itself is fast. Budget for cold startup plus 25%
// headroom; after the first successful read, owned local cache renders at once.
const COLD_ARTIFACT_STARTUP_MS=16000;
const measuredReadTimeout=(p95Ms:number)=>Math.ceil(p95Ms*1.25/250)*250;
const HOME_SIGNAL_TIMEOUT_MS=measuredReadTimeout(COLD_ARTIFACT_STARTUP_MS);
const MARKET_BRIEF_TIMEOUT_MS=measuredReadTimeout(COLD_ARTIFACT_STARTUP_MS);
const timeoutSeconds=(milliseconds:number)=>num(milliseconds/1000,2);
async function loadOpenSignalSummary(): Promise<OpenSignalSummaryLoad> {
 const cached=readOpenSignalCache();
 let timeoutHandle:ReturnType<typeof setTimeout>|undefined;
 const live=api.getOpenSignalSummary({}).then((summary)=>{const cachedAt=new Date().toISOString();try{localStorage.setItem(OPEN_SIGNAL_CACHE_KEY,JSON.stringify({summary,cachedAt}))}catch{/* cache is optional */}return {summary,source:"live" as const,cachedAt,fallbackReason:null};}).catch((error:unknown)=>{if(cached)return {...cached,fallbackReason:`Refresh failed: ${String(error).replace(/^Error:\s*/,"")}`};throw error;});
 const timeout=new Promise<OpenSignalSummaryLoad>((resolve,reject)=>{timeoutHandle=setTimeout(()=>{if(cached)resolve({...cached,fallbackReason:`Cached signals shown after the ${timeoutSeconds(HOME_SIGNAL_TIMEOUT_MS)} second cold-start budget.`});else reject(new Error(`The signal ledger did not finish within ${timeoutSeconds(HOME_SIGNAL_TIMEOUT_MS)} seconds. Retry once the artifact server has started.`));},HOME_SIGNAL_TIMEOUT_MS)});
 try{return await Promise.race([live,timeout]);}finally{if(timeoutHandle)clearTimeout(timeoutHandle);}
}
async function loadMarketBriefWithTimeout(): Promise<MarketBriefLoad> {
 const cached=readMarketBriefCache();
 let timeoutHandle:ReturnType<typeof setTimeout>|undefined;
 const live=api.getMarketDayBrief({}).then((brief)=>{const cachedAt=new Date().toISOString();try{localStorage.setItem(MARKET_BRIEF_CACHE_KEY,JSON.stringify({brief,cachedAt}))}catch{/* cache is optional */}return {brief,source:"live" as const,cachedAt,fallbackReason:null};}).catch((error:unknown)=>{if(cached)return {...cached,fallbackReason:`Refresh failed: ${String(error).replace(/^Error:\s*/,"")}`};throw error;});
 const timeout=new Promise<MarketBriefLoad>((resolve,reject)=>{timeoutHandle=setTimeout(()=>{if(cached)resolve({...cached,fallbackReason:`Cached brief shown after the ${timeoutSeconds(MARKET_BRIEF_TIMEOUT_MS)} second cold-start budget.`});else reject(new Error(`Market data did not finish within ${timeoutSeconds(MARKET_BRIEF_TIMEOUT_MS)} seconds. No cached market brief is available yet.`));},MARKET_BRIEF_TIMEOUT_MS)});
 try{return await Promise.race([live,timeout]);}finally{if(timeoutHandle)clearTimeout(timeoutHandle);}
}

function scrollToId(id:string){let tries=0;const tick=()=>{const el=document.getElementById(id);if(el){el.scrollIntoView({behavior:"smooth",block:"start"});return;}if(tries++<16)setTimeout(tick,250);};setTimeout(tick,80);}
export const POPULATION_LEGEND="Legacy rows were graded after the fact and are labeled retrospective; live rows grade only at their horizons.";
type PopulationKind="hypothesis"|"issued"|"legacy"|"timing"|"provenance"|"pending"|"fill"|"expiredUnfilled";
function PopulationChip({kind}:{kind:PopulationKind}){
 if(kind==="hypothesis")return <span className="pop-chip hypothesis">LIVE HYPOTHESIS · THEORY — NO ENTRY CONTRACT</span>;
 if(kind==="issued")return <span className="pop-chip issued">ISSUED / LIVE TRACKED CALL</span>;
 if(kind==="legacy")return <span className="pop-chip legacy">RETROSPECTIVE · LEGACY RECORD</span>;
 if(kind==="provenance")return <span className="pop-chip provenance">PROVENANCE-INCOMPLETE</span>;
 if(kind==="pending")return <span className="pop-chip timing">PENDING ENTRY · PAPER FILL RULE</span>;
 if(kind==="fill")return <span className="pop-chip issued">PAPER ENTRY FILLED · PAPER FILL RULE</span>;
 if(kind==="expiredUnfilled")return <span className="pop-chip legacy">EXPIRED UNFILLED · NEVER A POSITION</span>;
 return <span className="pop-chip timing">TIMING-UNVERIFIED</span>;
}
function fillChipKind(signal:TrackerSignal):PopulationKind|null{
 if(!signal.fillRuleVersion)return null;
 return signal.entryState==="pending_entry"?"pending":signal.entryState==="filled"?"fill":signal.entryState==="expired_unfilled"?"expiredUnfilled":null;
}
type NoDataEntry={metric:string;symbol:string;primarySource:string;fallback:string|null;lastAttemptAt:string|null;lastSuccessAt:string|null;result:string;nextRetry:string;classification:string};
function NoDataNote({entry}:{entry:NoDataEntry}){
 return <div className="no-data-note" role="note"><b>NO_DATA · {entry.metric.toUpperCase()} · {entry.symbol}</b><span>Source: {entry.primarySource} · fallback: {entry.fallback??"no suitable fallback exists"}</span><span>Last attempt {entry.lastAttemptAt?asOfLabel(entry.lastAttemptAt):"none recorded"} · result: {entry.result} · next retry: {entry.nextRetry}</span><span>Classification: {entry.classification}</span></div>;
}
function Section({title,children,right}:{title:string;children:React.ReactNode;right?:React.ReactNode}){return <section className="section"><div className="section-head"><h3>{title}</h3>{right}</div>{children}</section>}
function LaneBanner({children}:{children:string}){return <div className="lane-banner" role="note">{children}</div>}
const VIEW_LABEL: Record<string, string> = {
  opportunities: "OPPORTUNITIES — what changed · why it matters · timeframe · evidence and conflicts",
  asset: "ASSET — chart, thesis, history and paper records together",
  paper: "PAPER POSITIONS — issued entries · original rules · monitoring · outcomes",
  research: "RESEARCH — hypotheses · causal links · countercases · upcoming checks",
  diagnostics: "DIAGNOSTICS — provider failures · receipts · calibration · implementation detail",
};
function ViewBanner({ view }: { view: keyof typeof VIEW_LABEL }) { return <p className="eyebrow cyan view-label" role="note">{VIEW_LABEL[view]}</p>; }
function MetricGrid({items}:{items:Array<{label:string;value:string;tone?:string}>}){return <div className="metric-grid">{items.map((x)=><div className="metric" key={x.label}><small>{x.label}</small><b className={x.tone??""}>{x.value}</b></div>)}</div>}
function LoadingSkeleton({label}:{label:string}){return <div className="skeleton" aria-label={label}><span/><span/><div><i/><i/><i/></div></div>}
type InstrumentSuggestion = ApiResponse<typeof api,"searchInstruments">["suggestions"][number];
function InstrumentAutocomplete({input,setInput,choose,loading,home=false}:{input:string;setInput:(value:string)=>void;choose:(value:string)=>void;loading:boolean;home?:boolean}){
 const [open,setOpen]=useState(false); const [message,setMessage]=useState<string|null>(null); const term=input.trim();
 const search=useQuery({queryKey:["instrument-search",term.toLowerCase()],queryFn:()=>api.searchInstruments({query:term}),enabled:open&&term.length>=2,staleTime:10*60*1000});
 const pick=(suggestion:InstrumentSuggestion)=>{setOpen(false);setMessage(null);choose(suggestion.symbol)};
 const submit=async(event:FormEvent)=>{event.preventDefault();if(term.length<2)return;setOpen(true);setMessage(null);const result=await search.refetch();const suggestions=result.data?.suggestions??[];setMessage(suggestions.length?"Pick the exact listing below.":result.data?.note??"No listed instrument matched. Try a ticker or a more specific company name.")};
 return <form className={home?"home-search":"searchrow"} onSubmit={submit}><select aria-label={home?"Quick asset picker":"Asset picker"} value="" onChange={event=>event.target.value&&choose(event.target.value)}><option value="">{home?"QUICK PICK":"ASSET PICKER"}</option><option value="SPY">SPY · S&amp;P 500</option><option value="QQQ">QQQ · Nasdaq 100</option><option value="TLT">TLT · Treasuries</option><option value="GLD">GLD · Gold</option><option value="BTC-USD">BTC · Bitcoin</option></select><div className="instrument-typeahead"><input aria-label={home?"Ticker or company name":"Ticker or company"} value={input} onFocus={()=>setOpen(true)} onChange={event=>{setInput(event.target.value);setOpen(true);setMessage(null)}} autoComplete="off" aria-expanded={open&&!!search.data?.suggestions.length} aria-controls={home?"home-instrument-suggestions":"nav-instrument-suggestions"} placeholder={home?"Ticker or company name":"Ticker or company"}/>{open&&term.length>=2&&<div id={home?"home-instrument-suggestions":"nav-instrument-suggestions"} className="instrument-suggestions" role="listbox" aria-label="Matching listed instruments">{search.isFetching&&<div className="suggestion-state">SEARCHING YAHOO FINANCE…</div>}{!search.isFetching&&search.data?.suggestions.map(item=><button type="button" role="option" key={`${item.symbol}-${item.exchange}`} onMouseDown={event=>event.preventDefault()} onClick={()=>pick(item)}><span><b>{item.name}</b><small>{item.quoteType}</small></span><strong>{item.symbol}<small>{item.exchange} · {item.country}</small></strong></button>)}{!search.isFetching&&search.data?.note&&<div className="suggestion-state">{search.data.note}</div>}{message&&<div className="suggestion-state pick-required">{message}</div>}</div>}</div><button type="submit" disabled={term.length<2||loading||search.isFetching}>{search.isFetching?"SEARCHING…":loading?home?"ANALYZING…":"SCAN…":"FIND"}</button></form>
}
function Reliability({score}:{score:number}){const q=useQuery({queryKey:["tracker"],queryFn:()=>api.getSignalTracker({}),staleTime:5*60*1000});const band=ratingBand(score);const rows=q.data?.stats.filter(row=>row.agreementBand===band)??[];const samples=rows.reduce((sum,row)=>sum+row.samples,0);const hits=rows.reduce((sum,row)=>sum+row.hits,0);const grossAverage=samples?rows.reduce((sum,row)=>sum+row.avgReturn*row.samples,0)/samples:null;return <div className="reliability"><b>Fixed 30-session direction record · {band}</b>{q.isPending?<span>Loading accepted evaluations…</span>:samples?<span className={(grossAverage??0)>=0?"pos":"neg"}>{pct(grossAverage)} average gross return · {num(hits/samples*100)}% directional hits · {hits}/{samples} resolved · costs unknown</span>:<span>UNCALIBRATED · no resolved evaluations in this exact cohort</span>}</div>}
function TerminalNav({destination,switchDestination,className=""}:{destination:Destination;switchDestination:(destination:Destination)=>void;className?:string}){return <nav className={`tabs ${className}`.trim()} aria-label="Terminal destinations">{destinations.map(item=><button key={item} className={destination===item?"active":""} onClick={()=>switchDestination(item)}>{item}</button>)}</nav>}

function ageLabel(seconds:number|null){if(seconds==null)return "age unavailable";if(seconds<60)return `${seconds}s old`;if(seconds<3600)return `${Math.floor(seconds/60)}m old`;if(seconds<86400)return `${Math.floor(seconds/3600)}h old`;return `${Math.floor(seconds/86400)}d old`;}
function clockSkewLabel(eventAt:string|null,receivedAt:string|null){if(!eventAt||!receivedAt)return "";const skew=Math.round((Date.parse(eventAt)-Date.parse(receivedAt))/1000);return Number.isFinite(skew)&&skew>1?` · PROVIDER CLOCK +${skew}s VS RECEIPT`:"";}
function ageFromIso(iso:string|null|undefined){return iso&&Number.isFinite(Date.parse(iso))?Math.max(0,Math.floor((Date.now()-Date.parse(iso))/1000)):null;}
function MarketFreshness({symbol}:{symbol:string}){
 const qc=useQueryClient(); const q=useQuery({queryKey:["market-freshness",symbol],queryFn:()=>api.getMarketFreshness({symbol}),staleTime:60*1000}); const refresh=useMutation({mutationFn:()=>api.refreshMarketData({symbols:[symbol],trigger:"manual"}),onSuccess:()=>qc.invalidateQueries({queryKey:["market-freshness",symbol]})}); const row=q.data?.symbols[0];
 return <section className="freshness-panel" aria-label={`${symbol} market data freshness`}><header><div><span className="eyebrow">INDEPENDENT MARKET-DATA LANE</span><h2>Inputs &amp; timestamps</h2></div><button className="secondary" onClick={()=>refresh.mutate()} disabled={refresh.isPending}>{refresh.isPending?"REFRESHING…":"REFRESH MARKET DATA"}</button></header><p className="freshness-intro">Price, chart and volume refresh separately from the expensive dossier. The public feed may be delayed; fresh means current against its own timestamp threshold, not exchange real-time.</p>{refresh.error&&<div className="error">Refresh failed: {shortError(refresh.error)}</div>}{refresh.data&&<div className={`market-load-status ${refresh.data.status}`} role="status"><b>{refresh.data.status.toUpperCase()}</b><span>{refresh.data.symbols[0]?.observationsWritten??0} observations written · {refresh.data.symbols[0]?.observationsReused??0} deduplicated · {refresh.data.symbols[0]?.statusEventsAppended??0} status events</span></div>}{q.isPending?<LoadingSkeleton label="Loading input freshness"/>:row?<><div className="freshness-grid">{row.inputs.map(input=><article key={input.kind} className={input.stale||input.state==="error"?"stale":""}><div><span className={`status ${input.state}`}>{input.state.replace("_"," ")}</span><small>{input.candleState}</small></div><b>{input.label}</b><strong>{input.value==null?"—":num(input.value,4)}</strong><dl><div><dt>EVENT</dt><dd>{asOfLabel(input.eventAt)}</dd></div><div><dt>RECEIVED</dt><dd>{asOfLabel(input.receivedAt)}</dd></div><div><dt>PROVIDER AGE</dt><dd>{ageLabel(input.providerAgeSeconds)}</dd></div><div><dt>FETCH HEALTH</dt><dd>{ageLabel(input.fetchAgeSeconds)} since success</dd></div>{input.volume!=null&&<div><dt>OHLCV</dt><dd>{num(input.open,4)} / {num(input.high,4)} / {num(input.low,4)} / {num(input.close,4)} · provider raw volume {num(input.volume)} {input.volumeUnit.replace("_"," ")}</dd></div>}<div><dt>SOURCE</dt><dd>{input.source} · {input.venue}</dd></div><div><dt>POINTER</dt><dd>{input.observationId==null?"not applicable":`observation ${input.observationId} · refresh run ${input.refreshRunId??"—"}`}</dd></div>{input.contentHash&&<div><dt>RECEIPT</dt><dd>{input.contentHash}</dd></div>}</dl>{input.sourceUrl&&<a href={input.sourceUrl} target="_blank" rel="noreferrer">Observation source</a>}{clockSkewLabel(input.eventAt,input.receivedAt)&&<small>{clockSkewLabel(input.eventAt,input.receivedAt).replace(/^ · /,"")}</small>}<p>{input.entitlement}</p><details><summary>RAW → DISPLAYED TRACE</summary><code>{input.trace}</code></details>{input.error&&<span className="neg">{input.error}</span>}{(input.value==null||input.stale||input.state==="error")&&input.kind!=="expensive_analysis"&&<NoDataNote entry={{metric:input.label,symbol:row.symbol,primarySource:input.source,fallback:null,lastAttemptAt:input.lastAttemptAt??null,lastSuccessAt:input.lastSuccessAt??null,result:input.error??(input.stale?`Stale — the stored value keeps its own event time (${asOfLabel(input.eventAt)}) and is not presented as current.`:`No usable value (state ${input.state}).`),nextRetry:`next eligible ${asOfLabel(input.nextEligibleAt)}`,classification:input.state==="error"?"provider failure":input.state==="not_available"?(input.error?.includes("not been attempted")?"not applicable":"provider failure"):"stale"}}/>}</article>)}</div>{row.statusEvents.length>0&&<details className="freshness-events"><summary>APPENDED STATUS EVENTS · {row.statusEvents.length}</summary>{row.statusEvents.map((event,index)=><div key={`${event.signalId}-${event.status}-${event.observedAt}-${index}`}><b>{event.status.replaceAll("_"," ")}</b><span>Signal {event.signalId} · {asOfLabel(event.observedAt)} · {event.settlement}</span><p>{event.note}</p></div>)}</details>}<small className="freshness-note">{q.data?.note}</small></>:<div className="empty"><b>No market observation has been stored for {symbol}.</b><span>Refresh market data to create the first append-only observation.</span></div>}</section>;
}

function DossierTrackerLinks({symbol,openTape}:{symbol:string;openTape:(q:string)=>void}){
 const q=useQuery({queryKey:["tracker"],queryFn:()=>readWithDeadline(()=>api.getSignalTracker({limit:100}),"Signal tracker read"),staleTime:5*60*1000,retry:false});
 const rows=(q.data?.signals??[]).filter(signal=>signal.symbol===symbol);
 if(!rows.length)return null;
 return <section className="dossier-tracker-links" aria-label={`${symbol} tracked signals`}><span className="eyebrow">TRACKED SIGNALS FOR {symbol}</span><div className="form-actions">{rows.map(signal=><span key={signal.id} className="tracker-link-item"><PopulationChip kind={signal.timingUnverified?"timing":signal.population==="legacy"?"legacy":"issued"}/>{signal.provenanceIncomplete&&<PopulationChip kind="provenance"/>}<button className="secondary" onClick={()=>{openTape(symbol);scrollToId(`tracker-signal-${signal.id}`);}} aria-label={`Open tracker row for signal ${signal.id}`}>TRACKER #{signal.id} · {signal.direction.toUpperCase()} · {signal.signalDate}</button></span>)}</div></section>;
}
function AtGlanceVerdict({a,tab,setTab,onWatch,watching,onTrack,tracking,trackNote}:{a:Analysis;tab:Tab;setTab:(tab:Tab)=>void;onWatch:()=>void;watching:boolean;onTrack:()=>void;tracking:boolean;trackNote:string|null}){
 const instrument=a.instrument;
 const live=useQuery({queryKey:["market-freshness",instrument?.symbol],queryFn:()=>api.getMarketFreshness({symbol:instrument?.symbol??""}),enabled:!!instrument?.symbol,staleTime:30*1000});
 const history=useQuery({queryKey:["dossier-history",instrument?.symbol,a.delivery.generatedAt],queryFn:()=>api.getdossierhistory({symbol:instrument?.symbol??""}),enabled:!!instrument?.symbol,staleTime:5*60*1000});
 const previousReads=(history.data?.reads??[]).filter(read=>read.tradingDay!==a.delivery.tradingDay);
 const liveInputs=live.data?.symbols[0]?.inputs??[]; const liveQuote=liveInputs.find(input=>input.kind==="quote"); const liveCandle=liveInputs.find(input=>input.kind==="forming_candle")??liveInputs.find(input=>input.kind==="completed_candle"); const markObservation=liveQuote?.value!=null?liveQuote:null; const currentPrice=markObservation?.value??instrument?.price??null; const markEventAt=markObservation?.eventAt??instrument?.asOf??null; const markStale=markObservation?markObservation.stale||markObservation.state!=="fresh":isStale(instrument?.asOf);
 const score=a.factorModel?.score;
 const previousRead=previousReads[0]??null;
 const changedSinceLast=previousRead&&score!=null?(previousRead.direction!==a.factorModel?.direction?`Direction changed from ${previousRead.direction.toUpperCase()} to ${(a.factorModel?.direction??"mixed").toUpperCase()}.`:`Factor agreement moved from ${previousRead.score>0?"+":""}${previousRead.score} to ${score>0?"+":""}${score} (${score-previousRead.score>0?"+":""}${score-previousRead.score}).`):"No preceding stored trading-day read is available for comparison.";
 const hasAssessment=score!=null;
 const direction=a.factorModel?.direction??a.levels?.direction??"mixed";
 const walkForwardObservations=a.walkForward?.observations??0;
 const walkForwardStatus=a.walkForward?.qualified?"BASELINE COVERAGE SUFFICIENT":"BASELINE COVERAGE THIN";
 if(!instrument)return null;
 return <section id={`dossier-${instrument.symbol}`} className={`verdict-board ${direction}`} aria-label={`${instrument.symbol} directional factor agreement`}>
  <div className="verdict-lead">
   <div className="verdict-identity"><span className="eyebrow">{instrument.symbol} · {instrument.name}</span><div className="price"><strong>{quoteMoney(currentPrice,instrument.currency)}</strong><span className={(instrument.changePercent??0)>=0?"pos":"neg"}>SESSION Δ {pct(instrument.changePercent)}</span></div><small>{markObservation?`${markStale?"LAST KNOWN MARK":"CURRENT MARK"} · ${markObservation.source} · ${markObservation.venue} · event ${asOfLabel(markObservation.eventAt)} · received ${asOfLabel(markObservation.receivedAt)} · fetch success ${asOfLabel(markObservation.lastSuccessAt)} · observation ${markObservation.observationId??"unavailable"}`:`LAST KNOWN MARK · event ${asOfLabel(instrument.asOf)} · receipt/source pointer unavailable`} · SESSION CHANGE FROM ANALYSIS SNAPSHOT {asOfLabel(instrument.asOf)}{liveCandle?.volume!=null?` · ${liveCandle.candleState==="forming"?"FORMING DAILY CANDLE":"COMPLETED DAILY CANDLE"} PROVIDER RAW VOLUME ${num(liveCandle.volume)} ${liveCandle.volumeUnit.replace("_"," ")} · ${liveCandle.venue} · event ${asOfLabel(liveCandle.eventAt)} · not quote-currency notional`:""}</small></div>
   <div className="verdict-call"><small>FACTOR AGREEMENT · NOT A PROBABILITY</small><strong>{hasAssessment?direction.toUpperCase():"NOT EVALUATED"}</strong><span>{score==null?"NO VALID SCORE":`${score>0?"+":""}${score} / 100`}</span><div className="previous-reads change-read"><small>WHAT CHANGED SINCE LAST VIEW</small><b>{changedSinceLast}</b><span>{previousReads.length?previousReads.slice(0,3).map(read=>`${read.score>0?"+":""}${read.score} ${read.direction} · ${read.tradingDay}`).join("  →  "):"Comparison starts after the next stored trading-day dossier read."}</span></div></div>
   <div className="verdict-confidence"><small>LEGACY BASELINE REPLAY COVERAGE · NOT SIGNAL VALIDATION</small><b>{walkForwardStatus}</b><strong>EDGE UNVALIDATED</strong><span>{walkForwardObservations} replay observations{a.walkForward?.qualified&&a.walkForward.hitRate!=null&&a.walkForward.averageDirectionalReturn!=null?` · ${num(a.walkForward.hitRate)}% directional hit · ${pct(a.walkForward.averageDirectionalReturn)} avg return · edge not validated`:` · fewer than 20 baseline observations`}</span></div>
  </div>
  <div className="verdict-meta-grid" aria-label="Assessment contract"><span><small>ASSESSMENT</small><b>{hasAssessment?`${direction.toUpperCase()} · RESEARCH`:"NOT EVALUATED"}</b></span><span><small>HORIZON</small><b>30 trading sessions</b></span><span><small>ANALYSIS AS OF</small><b>{asOfLabel(a.delivery.generatedAt)}</b></span><span><small>MARKET DATA AS OF</small><b>{asOfLabel(markEventAt)}</b></span><span><small>HISTORY COVERAGE</small><b>{instrument.coversLatestCompletedSession?`COMPLETED THROUGH ${instrument.newestCompletedBarDate??"—"}`:`BEHIND LATEST COMPLETED SESSION ${instrument.latestCompletedSessionDate}`}</b></span><span><small>HISTORY SOURCE</small><b>{instrument.historyServedFromCache?"STORED COPY":"PROVIDER FETCH"}</b></span><span><small>QUOTE STATE</small><b>{instrument.quoteState.replace("_"," ").toUpperCase()}</b></span><span><small>FRESHNESS</small><b>{markStale?"STALE":"CURRENT TO SOURCE"}</b></span><span><small>VALIDATION</small><b>EDGE UNVALIDATED</b></span><span><small>COHORT</small><b>Research · v3.1</b></span><span><small>ELIGIBILITY</small><b>{hasAssessment&&direction!=="mixed"?"RESEARCH ASSESSMENT ONLY":"NOT ELIGIBLE"}</b></span></div>
  <div className="verdict-levels">
   <div><small>ENTRY ZONE</small><b>{a.levels?`${quoteMoney(a.levels.entryLow,instrument.currency)}–${quoteMoney(a.levels.entryHigh,instrument.currency)}`:"Unavailable"}</b></div>
   <div><small>INVALIDATION</small><b className="neg">{quoteMoney(a.levels?.invalidation,instrument.currency)}</b>{a.levels&&<span>{num(a.levels.invalidationAtrMultiple,2)}× Wilder ATR-14 · ATR {quoteMoney(a.levels.atr14,instrument.currency)}</span>}</div>
   <div><small>TARGET 1 (CHART)</small><b>{quoteMoney(a.levels?.target1,instrument.currency)}</b></div>
   <div><small>TARGET 2 (CHART)</small><b>{quoteMoney(a.levels?.target2,instrument.currency)}</b></div>
  </div>
  {a.levels&&<details className="calculation-note level-calculation"><summary>HOW THE ENTRY, INVALIDATION AND TARGETS ARE CALCULATED</summary><p><b>Entry zone</b> = accepted entry ± 0.25 × risk unit. <b>Invalidation</b> = accepted entry moved against the {a.levels.direction} direction by {num(a.levels.invalidationAtrMultiple,2)} × Wilder ATR-14. <b>Target 1</b> = entry + 1.5R in the assessment direction; <b>Target 2</b> = entry + 2.5R. Here, R is the absolute distance from accepted entry to invalidation. Stored risk input: {quoteMoney(a.levels.atr14,instrument.currency)}.</p></details>}
  <div className="verdict-thesis"><small>THESIS</small><p>{a.thesis??"Thesis unavailable for this fetch."}</p></div>
  <div className="verdict-kill"><small>WHAT KILLS IT</small><p>{a.failure??"No validated invalidation tripwire is available."}</p><span>DISCONFIRMING EVIDENCE · n={a.factorModel?.factors.filter(factor=>factor.score<0).length??0}</span>{a.factorModel&&a.factorModel.factors.some(factor=>factor.quality!=="GOOD")&&<span>KNOWN GAPS · {a.factorModel.factors.filter(factor=>factor.quality!=="GOOD").map(factor=>factor.name).join(", ")}</span>}</div>
  {score!=null&&<Reliability score={score}/>} 
  <div className="verdict-foot"><span className={markStale?"stale":"fresh"}>{markStale?"STALE":"FRESH"}</span><span>{markObservation?`${markObservation.source} · ${markObservation.venue} · event ${asOfLabel(markObservation.eventAt)} · received ${asOfLabel(markObservation.receivedAt)} · last successful fetch ${asOfLabel(markObservation.lastSuccessAt)} · observation ${markObservation.observationId??"unavailable"}`:`Legacy source event ${asOfLabel(instrument.asOf)} · receipt/source pointer unavailable`}</span><span>Factor agreement, not profit probability</span><button className="secondary compact" onClick={onWatch} disabled={watching}>{watching?"ADDING…":"+ WATCH"}</button><button className="secondary compact" onClick={onTrack} disabled={tracking||a.factorModel?.direction==="mixed"}>{tracking?"TRACKING…":"TRACK THIS"}</button></div>{trackNote&&<div className="notice">{trackNote}</div>}
  {a.factorModel&&<details className="verdict-ledger"><summary>WHY · FACTOR LEDGER</summary><div className="notice formula"><b>Freshness:</b> {a.factorModel.freshness}</div>{a.levels&&<div className="notice formula"><b>Invalidation basis:</b> {a.levels.invalidationBasis}. Wilder ATR-14 = {quoteMoney(a.levels.atr14,instrument.currency)}; applies symmetrically to long and short setups.</div>}<div className="factor-table" role="table" aria-label={`${instrument.symbol} factor ledger`}><div className="factor-row factor-head" role="row"><span>Factor</span><span>Weight</span><span>Score</span><span>Contribution</span></div>{a.factorModel.factors.map(factor=>{const seconds=ageFromIso(factor.asOf);const stale=seconds==null||seconds>86400;return <div className={`factor-row ${factor.quality.toLowerCase()}`} role="row" key={factor.name}><span><b>{factor.name}</b><small>{factor.reading}</small><small>{factor.source} · event {asOfLabel(factor.asOf)} · observation age {ageLabel(seconds)} · {instrument.historyServedFromCache?`stored history · retrieved ${asOfLabel(instrument.historyRetrievedAt)}`:`history retrieved ${asOfLabel(instrument.historyRetrievedAt)}`} · {stale?"STALE":"FRESH"} · {factor.quality}</small>{instrument.historyProviderError&&<small className="neg">Latest provider fetch failed ({instrument.historyProviderError}); stored history was disclosed, not refreshed.</small>}{factor.quality!=="GOOD"&&<small>{factor.qualityReason}</small>}</span><span>{factor.weight}</span><span className={factor.score>0?"pos":factor.score<0?"neg":""}>{factor.score>0?"+":""}{factor.score}</span><span>{factor.contribution>0?"+":""}{factor.contribution}</span></div>})}</div><div className="notice formula"><b>Formula:</b> {a.factorModel.formula}</div></details>}
  <nav className="instrument-actions" aria-label={`${instrument.symbol} analysis views`}>{(["DOSSIER","SIGNAL TAPE","SMART MONEY","WATCHLIST"] as const).map(view=><button key={view} className={tab===view?"active":""} onClick={()=>setTab(view)}>{view==="WATCHLIST"?"ENTRY CHECK":view==="SIGNAL TAPE"?"SIGNALS":view}</button>)}</nav>
 </section>
}

export function App(){
 const qc=useQueryClient();
 const initialSymbol=useMemo(()=>new URLSearchParams(window.location.search).get("symbol")?.trim()??"",[]);
 const [destination,setDestination]=useState<Destination>(initialSymbol?"DOSSIER":"TODAY");
 const [researchSection,setResearchSection]=useState<ResearchSection>("NEWS");
 const [logSection,setLogSection]=useState<LogSection>("WATCHLIST");
 const [input,setInput]=useState(initialSymbol);
 const [query,setQuery]=useState(initialSymbol);
 const [chartMode,setChartMode]=useState<"line"|"candles">("line");
 const [recent,setRecent]=useState<string[]>(()=>{try{return JSON.parse(localStorage.getItem("equity-terminal-recent")??"[]") as string[]}catch{return []}});
 const analysis=useQuery({queryKey:["analysis",query],queryFn:()=>api.analyzeInstrument({symbol:query}),enabled:query.length>0,staleTime:5*60*1000});
 const a=analysis.data;
 const addWatch=useMutation({mutationFn:()=>api.addWatch({query:a?.instrument?.symbol??query}),onSuccess:()=>qc.invalidateQueries({queryKey:["watchlist"]})});
 const trackSignal=useMutation({mutationFn:()=>api.trackAnalyzedSignal({query:a?.instrument?.symbol??query}),onSuccess:()=>{qc.invalidateQueries({queryKey:["tracker"]});qc.invalidateQueries({queryKey:["radar"]})}});
 const setSymbolUrl=(symbol:string)=>{const params=new URLSearchParams(window.location.search);params.set("symbol",symbol.toUpperCase());window.history.replaceState({},"",`${window.location.pathname}?${params.toString()}`)};
 const loadSymbol=(value:string,next:Destination)=>{const symbol=value.trim();if(!symbol)return;setRecent(items=>{const nextItems=[symbol,...items.filter(item=>item.toUpperCase()!==symbol.toUpperCase())].slice(0,5);localStorage.setItem("equity-terminal-recent",JSON.stringify(nextItems));return nextItems});setInput(symbol);setQuery(symbol);setSymbolUrl(symbol);setDestination(next)};
 const choose=(value:string)=>loadSymbol(value,"DOSSIER");
 const openTape=(value:string)=>loadSymbol(value,"SIGNALS");
 const routeLegacy=(next:Tab)=>{
  if(next==="MARKET")setDestination("TODAY");
  else if(next==="DOSSIER")setDestination("DOSSIER");
  else if(next==="SIGNAL TAPE")setDestination("SIGNALS");
  else if(next==="WATCHLIST"||next==="ALERTS"||next==="JOURNAL"){setLogSection(next);setDestination("LOG");}
  else {const section:ResearchSection=next==="DISCOVERY LANE"?"DISCOVERY":next==="CROWD"?"CROWD":next==="SMART MONEY"?"SMART MONEY":next==="THEORIES"?"THEORIES":next==="ENGINE HITS"?"ENGINE HITS":"NEWS";setResearchSection(section);setDestination("RESEARCH");}
 };
 const legacyTab:Tab=destination==="DOSSIER"?"DOSSIER":destination==="SIGNALS"?"SIGNAL TAPE":destination==="LOG"?logSection:destination==="RESEARCH"?(researchSection==="DISCOVERY"?"DISCOVERY LANE":researchSection):"MARKET";
 const assetReady=query?analysis.isPending?<LoadingSkeleton label="Loading market evidence"/>:analysis.error?<><div className="error">Analysis failed: {shortError(analysis.error)}</div><details><summary>Technical details</summary><pre>{techDetail(analysis.error)}</pre></details></>:a?.status==="error"?<><div className="error">{shortError(a.error)}</div><details><summary>Technical details</summary><pre>{techDetail(a.error)}</pre></details></>:a?.status==="private"&&a.privateCompany?<PrivatePanel data={a.privateCompany} choose={choose}/>:null:null;
 const analysisPanel:Analysis|null=query&&!analysis.isPending&&!analysis.error&&a?.status!=="error"&&!(a?.status==="private"&&a.privateCompany)&&a?a:null;
 const dossierSurface=!query?<InstrumentPrompt onFocus={()=>document.querySelector<HTMLInputElement>(".searchrow input")?.focus()}/>:assetReady??(analysisPanel?<>
  <ViewBanner view="asset"/>
  <LaneBanner>INVESTMENT RESEARCH — assessments and theses, not trades.</LaneBanner>
  {analysisPanel.instrument&&<>
   <AtGlanceVerdict a={analysisPanel} tab={legacyTab} setTab={routeLegacy} onWatch={()=>addWatch.mutate()} watching={addWatch.isPending} onTrack={()=>trackSignal.mutate()} tracking={trackSignal.isPending} trackNote={trackSignal.data?.note??null}/>
   <DossierTrackerLinks symbol={analysisPanel.instrument.symbol} openTape={openTape}/>
   <MarketFreshness symbol={analysisPanel.instrument.symbol}/>
   <AssetContextPanel symbol={analysisPanel.instrument.symbol}/>
   <AssetEvidenceSection symbol={analysisPanel.instrument.symbol}/>
   <DossierSynthesis a={analysisPanel}/>
   <ValuationBlock key={analysisPanel.instrument.symbol} symbol={analysisPanel.instrument.symbol} initialData={analysisPanel.valuation}/>
   {analysisPanel.commodity&&<div className="notice instrument-note"><b>Plotted: {analysisPanel.instrument.symbol}.</b> {analysisPanel.commodity.why}</div>}
   {analysisPanel.instrument.resolutionMethod==="symbol_search"&&<div className="matchline instrument-note">Resolved from “{analysisPanel.instrument.resolvedFrom}” via Yahoo Finance symbol/name search.</div>}
   {addWatch.data?.error&&<div className="error instrument-note">{addWatch.data.error}</div>}
   <Dossier a={analysisPanel} mode={chartMode} setMode={setChartMode}/>
   <Research a={analysisPanel}/>
  </>}
 </>:null);
 const signalAssetSurface=!query?null:assetReady??(analysisPanel?<>
  {analysisPanel.instrument&&<><AtGlanceVerdict a={analysisPanel} tab={legacyTab} setTab={routeLegacy} onWatch={()=>addWatch.mutate()} watching={addWatch.isPending} onTrack={()=>trackSignal.mutate()} tracking={trackSignal.isPending} trackNote={trackSignal.data?.note??null}/><MarketFreshness symbol={analysisPanel.instrument.symbol}/></>}
  <SignalTape query={query} openDossier={()=>setDestination("DOSSIER")}/>
 </>:null);
 return <div className="app"><SafeAreaTopScrim backgroundColor="var(--bg)"/><main className="shell">
  <div className="searchbar"><TerminalNav destination={destination} switchDestination={setDestination} className="primary-nav"/>{destination!=="TODAY"&&destination!=="LOG"&&<div className="query-builder"><InstrumentAutocomplete input={input} setInput={setInput} choose={destination==="SIGNALS"?openTape:choose} loading={analysis.isFetching}/></div>}</div>
  {destination==="TODAY"&&<Today choose={choose} openTape={openTape} openTab={routeLegacy} input={input} setInput={setInput} recent={recent} loading={analysis.isFetching}/>} 
  {destination==="DOSSIER"&&dossierSurface}
  {destination==="SIGNALS"&&<><div className="destination-intro"><span className="eyebrow">SIGNALS</span><h1>Setups, evidence and measured outcomes</h1><p>Asset tape first, then the unchanged trial, discovery, radar and grading ledgers.</p></div><LaneBanner>CHART OPPORTUNITIES — observations only. No entries, no targets, no sizing.</LaneBanner>{signalAssetSurface}<Scorecard/><Radar choose={choose} openTape={openTape}/><AutoScan choose={choose} openTape={openTape} qc={qc}/><Tracker openTape={openTape} choose={choose} openBoard={(symbol)=>{setDestination("TODAY");scrollToId(`board-row-${symbol}`);}}/></>}
  {destination==="RESEARCH"&&<ResearchHub section={researchSection} setSection={setResearchSection} symbol={a?.instrument?.symbol??query} analysis={analysisPanel} choose={choose} openTape={openTape} openTab={routeLegacy} qc={qc}/>} 
  {destination==="LOG"&&<LogHub section={logSection} setSection={setLogSection} symbol={a?.instrument?.symbol??query} analysis={analysisPanel} choose={choose} qc={qc}/>} 
 </main></div>;
}

function DestinationSections<T extends string>({label,items,value,onChange}:{label:string;items:readonly T[];value:T;onChange:(value:T)=>void}){
 return <nav className="destination-sections" aria-label={label}>{items.map(item=><button key={item} className={value===item?"active":""} onClick={()=>onChange(item)}>{item}</button>)}</nav>;
}
function Today({choose,openTape,openTab,input,setInput,recent,loading}:{choose:(q:string)=>void;openTape:(q:string)=>void;openTab:(tab:Tab)=>void;input:string;setInput:(value:string)=>void;recent:string[];loading:boolean}){
 return <div className="today"><ViewBanner view="opportunities"/><Opportunities choose={choose} openTape={openTape} openTab={openTab}/><TodayEngineHits/><HomePicker input={input} setInput={setInput} choose={choose} recent={recent} loading={loading}/></div>;
}
function TodayEngineHits(){
 const q=useQuery({queryKey:["engine-hits"],queryFn:()=>api.getEngineHits({}),staleTime:5*60*1000});
 const fresh=(q.data?.hits??[]).filter(hit=>!isStale(hit.hitAt)).slice(0,3);
 return <section className="today-hits" aria-label="Fresh engine hits"><div className="section-head"><div><span className="eyebrow">EVIDENCE CHANGES</span><h2>Fresh Engine Hits</h2></div></div>{q.isPending?<LoadingSkeleton label="Loading fresh Engine Hits"/>:q.error?<div className="error">Engine Hits failed: {shortError(q.error)}</div>:fresh.length?<div className="today-hit-list">{fresh.map(hit=><article key={hit.id}><header><span className={`status ${hit.kind==="gem"?"confirming":"live"}`}>{hit.kind==="gem"?"GEM":hit.testCaseLabel}</span><time>{asOfLabel(hit.hitAt)}</time></header><b>{hit.symbol??hit.triggerEvent}</b><p>{hit.thesis}</p><small>{hit.evidence.length} source{hit.evidence.length===1?"":"s"} · score {hit.evidenceStrength??hit.engineScore}</small></article>)}</div>:<div className="empty"><b>No fresh Engine Hits.</b><span>The stored hit log has no evidence change inside the current freshness window.</span></div>}</section>;
}
function ResearchHub({section,setSection,symbol,analysis,choose,openTape,openTab,qc}:{section:ResearchSection;setSection:(value:ResearchSection)=>void;symbol:string;analysis:Analysis|null;choose:(q:string)=>void;openTape:(q:string)=>void;openTab:(tab:Tab)=>void;qc:ReturnType<typeof useQueryClient>}){
 const sections=["NEWS","CROWD","SMART MONEY","THEORIES","DISCOVERY","ENGINE HITS"] as const;
 return <div className="destination-page"><ViewBanner view="research"/><div className="destination-intro"><span className="eyebrow">RESEARCH</span><h1>Evidence, narratives and discovery</h1><p>One workspace; switch the evidence lane without losing the selected asset.</p></div><LaneBanner>INVESTMENT RESEARCH — assessments and theses, not trades.</LaneBanner><DestinationSections label="Research sections" items={sections} value={section} onChange={setSection}/>{section==="NEWS"&&<News symbol={symbol} qc={qc}/>} {section==="CROWD"&&<Crowd/>} {section==="SMART MONEY"&&(analysis?<SmartMoney a={analysis}/>:<MarketSmartMoney openTab={openTab}/>)} {section==="THEORIES"&&<Theories qc={qc} choose={choose}/>} {section==="DISCOVERY"&&<><EquityScanNow qc={qc}/><DiscoveryLane choose={choose} qc={qc}/><FilteredObservations/><MarketHome choose={choose} openTab={openTab}/><VolRegimeStrip/><CotPositioningStrip/><OpenbbSupplementStrip/></>} {section==="ENGINE HITS"&&<EngineHits/>}<div className="research-signal-link"><button className="secondary" onClick={()=>symbol&&openTape(symbol)} disabled={!symbol}>OPEN {symbol||"ASSET"} SIGNALS</button></div></div>;
}
function LogHub({section,setSection,symbol,analysis,choose,qc}:{section:LogSection;setSection:(value:LogSection)=>void;symbol:string;analysis:Analysis|null;choose:(q:string)=>void;qc:ReturnType<typeof useQueryClient>}){
 const sections=["WATCHLIST","ALERTS","JOURNAL"] as const;
 return <div className="destination-page"><ViewBanner view="paper"/><div className="destination-intro"><span className="eyebrow">LOG</span><h1>Watches, alerts and decisions</h1><p>The operational record: what is watched, what fired, and what you logged.</p></div><DestinationSections label="Log sections" items={sections} value={section} onChange={setSection}/>{section==="WATCHLIST"&&<><Watchlist choose={choose} qc={qc}/>{symbol&&<Sizing key={symbol} symbol={symbol} price={analysis?.instrument?.price??0} invalidation={analysis?.levels?.invalidation??0} volatility={(()=>{const atr=analysis?.indicators.find(x=>x.label==="ATR 14")?.value,px=analysis?.instrument?.price;return atr&&px?atr/px>=.06?"high":atr/px>=.03?"elevated":"normal":"unavailable"})()}/>}</>} {section==="ALERTS"&&<Alerts qc={qc} choose={choose}/>} {section==="JOURNAL"&&<><Journal symbol={symbol} qc={qc} choose={choose}/><Rules qc={qc}/></>}</div>;
}

const DAILY_CARD_SYMBOLS=["MDLZ","WMT","SI=F","GC=F","CL=F","6411.TWO","0221.KL"] as const;
const SOURCE_VERSION="equity-homepage-e2e-2026-10-15.4";
function SchedulerInvocationLabel({receipt,pending}:{receipt:SchedulerReceipt|null|undefined;pending:boolean}){
 if(pending)return <strong>LOADING RECEIPT…</strong>;
 if(!receipt)return <strong>UNVERIFIED</strong>;
 return <strong>{receipt.status.toUpperCase()} · {asOfLabel(receipt.invokedAt)} · {receipt.runId}</strong>;
}
function DailyTerminal({openTape}:{openTape:(q:string)=>void}){
 const qc=useQueryClient();
 const scan=useQuery({queryKey:["auto-scan-home"],queryFn:()=>api.getAutoScan({}),staleTime:60*1000,retry:false});
 const freshness=useQuery({queryKey:["market-freshness-all"],queryFn:()=>api.getMarketFreshness({}),staleTime:60*1000,retry:false});
 const signals=useQuery({queryKey:["open-signal-summary-bounded"],queryFn:loadOpenSignalSummary,staleTime:60*1000,retry:false});
 const grading=useQuery({queryKey:["measurement-run-latest"],queryFn:()=>api.getLatestMeasurementRun({}),staleTime:60*1000,retry:false});
 const scheduler=useQuery({queryKey:["scheduler-invocations"],queryFn:()=>api.getSchedulerInvocations({}),staleTime:30*1000,retry:false});
 const refresh=useMutation({mutationFn:()=>api.refreshMarketData({symbols:[...DAILY_CARD_SYMBOLS],trigger:"manual"}),onSuccess:async()=>{await Promise.all([qc.invalidateQueries({queryKey:["market-freshness-all"]}),qc.invalidateQueries({queryKey:["open-signal-summary-bounded"]})])}});
 const reasonCounts=useMemo(()=>{const counts=new Map<string,number>();for(const row of scan.data?.diagnostics??[])counts.set(row.reasonCode,(counts.get(row.reasonCode)??0)+1);return [...counts.entries()].sort((a,b)=>b[1]-a[1]);},[scan.data?.diagnostics]);
 const run=scan.data?.run; const accounting=scan.data?.accounting; const evaluation=grading.data;
 const schedulerReceipt=(jobKey:"discovery_scan"|"signal_postmortem"|"market_data_refresh")=>scheduler.data?.jobs.find(job=>job.jobKey===jobKey)?.latest;
 return <section className="daily-terminal" aria-label="Today's terminal run">
  <ViewBanner view="diagnostics"/>
  <header><div><span className="eyebrow">DAILY TERMINAL · SOURCE {SOURCE_VERSION}</span><h1>What the terminal checked</h1><p>Discovery, market marks and outcome grading are separate ledgers. A quiet day is shown as a checked day—not as an unchanged homepage.</p></div><button className="secondary" onClick={()=>refresh.mutate()} disabled={refresh.isPending}>{refresh.isPending?"REFRESHING 7 CARDS…":"REFRESH 7 CARDS"}</button></header>
  {refresh.error&&<div className="error">Card refresh failed: {String(refresh.error).replace(/^Error:\s*/,"")}</div>}
  {refresh.data&&<div className={`market-load-status ${refresh.data.status}`}><b>REFRESH RUN {refresh.data.runId}</b><span>{refresh.data.status.toUpperCase()} · started {asOfLabel(refresh.data.startedAt)} · finished {asOfLabel(refresh.data.finishedAt)} · {refresh.data.symbols.filter(row=>row.status!=="error").length} succeeded · {refresh.data.symbols.filter(row=>row.status==="error").length} failed</span></div>}
  <div className="daily-ledgers">
   <article><small>DISCOVERY SCAN</small><b>{run?`RUN ${run.id} · ${run.status.toUpperCase()}`:"NO RUN"}</b><span>{run?`${run.universe.toUpperCase()} · computed ${asOfLabel(run.stamps.computedAt)} · data through session ${run.stamps.dataThroughSession??"unavailable"} · last success ${asOfLabel(run.lastSuccessAt)}`:"No persisted scan run."}</span><p>Trigger: runAutomatedScan. Scheduler invocation: <SchedulerInvocationLabel receipt={schedulerReceipt("discovery_scan")} pending={scheduler.isPending}/>.</p></article>
   <article><small>OUTCOME GRADING</small><b>{evaluation?`${evaluation.runId} · ${evaluation.status.toUpperCase()}`:"NO RUN LEDGER"}</b><span>{evaluation?`started ${asOfLabel(evaluation.startedAt)} · completed ${asOfLabel(evaluation.completedAt)} · ${evaluation.counts.evaluated}/${evaluation.counts.inScope} evaluated · ${evaluation.counts.excluded} excluded · ${evaluation.counts.failed} failed`:"No successful persisted grading run is available."}</span><p>Trigger: runDailySignalPostmortem. Scheduler invocation: <SchedulerInvocationLabel receipt={schedulerReceipt("signal_postmortem")} pending={scheduler.isPending}/>.</p>{evaluation&&<details className="grading-dispositions"><summary>PER-ROW DISPOSITIONS · {evaluation.items.length}</summary><div>{evaluation.items.map(item=><div key={item.signalId}><b>{item.symbol??`#${item.signalId}`}</b><span>{String(item.gradingState).replaceAll("_"," ").toUpperCase()}</span><small>{item.reasonCode?String(item.reasonCode).replaceAll("_"," "):""}{item.reason?` · ${item.reason}`:""}</small></div>)}</div></details>}</article>
   <article><small>PRICE REFRESH</small><b>{freshness.data?.lastRun?`RUN ${freshness.data.lastRun.id} · ${freshness.data.lastRun.status.toUpperCase()}`:"NO RUN LEDGER"}</b><span>{freshness.data?.lastRun?`${asOfLabel(freshness.data.lastRun.startedAt)} → ${asOfLabel(freshness.data.lastRun.finishedAt)} · ${freshness.data.lastRun.refreshedCount}/${freshness.data.lastRun.requestedCount} refreshed · ${freshness.data.lastRun.errorCount} failed`:"No persisted refresh run is available."}</span><p>Trigger: refreshMarketData / runMarketDataRefresh. Scheduler invocation: <SchedulerInvocationLabel receipt={schedulerReceipt("market_data_refresh")} pending={scheduler.isPending}/>.</p></article>
  </div>
  {accounting&&<div className="coverage-strip" aria-label="Latest scan coverage">{Object.entries(accounting).map(([label,value])=><span key={label}><small>{label.replace(/([A-Z])/g," $1")}</small><b>{value}</b></span>)}</div>}
  <div className="scan-reasons"><div><b>REJECTION / ABSTENTION REASONS</b>{reasonCounts.length?reasonCounts.map(([reason,count])=><span key={reason}>{reason.replaceAll("_"," ")} · {count}</span>):<span>No per-symbol reason rows are attached to this run.</span>}</div><div><b>{scan.data?.signals.length?"NEW QUALIFYING CANDIDATES":`QUALIFYING CANDIDATES · 0`}</b>{scan.data?.signals.length?scan.data.signals.slice(0,8).map(candidate=><button key={candidate.id} onClick={()=>openTape(candidate.symbol)}>{candidate.symbol} · {candidate.direction} · {candidate.agreementScore>0?"+":""}{candidate.agreementScore}</button>):<span>None in the latest persisted run. No signal was forced.</span>}</div></div>
  {scan.data?.diagnostics.length?<details className="scan-diagnostics"><summary>PER-SYMBOL STRATEGY EVALUATIONS · {scan.data.diagnostics.length}</summary><p>Rating requires a non-mixed factor direction and at least four measured dimensions. Future diagnosis rows persist each dimension's status, values and thresholds; older rows retain only the reason saved at their run time.</p><div>{scan.data.diagnostics.map(row=><article key={`${row.symbol}-${row.attemptedAt}`}><b>{row.symbol}</b><span>{row.outcome.toUpperCase()} · {row.reasonCode.replaceAll("_"," ")} · {row.stage.replaceAll("_"," ")}</span><small>{row.reason}</small><small>provider {row.providerStatus??"no response"} · event {asOfLabel(row.providerEventAt)} · attempted {asOfLabel(row.attemptedAt)} · completed {asOfLabel(row.completedAt)}</small></article>)}</div></details>:null}
  <div className="evidence-card-grid">{DAILY_CARD_SYMBOLS.map(symbol=>{const market=freshness.data?.symbols.find(row=>row.symbol===symbol);const quote=market?.inputs.find(input=>input.kind==="quote");const signal=signals.data?.summary.signals.find(row=>row.symbol===symbol);const levelOutcome=signal?markOutcome(signal.direction,quote?.value??signal.currentPrice,signal.invalidationLevel,signal.target1):null;const state=levelOutcome?`LOGBOOK · ${levelOutcome}`:signal?`${signal.tradeState.toUpperCase()} · EVALUATION ${signal.gradingState.replaceAll("_"," ").toUpperCase()}`:"NO ACTIVE LEGACY SIGNAL";return <button key={symbol} onClick={()=>openTape(symbol)} aria-label={`Open ${symbol} evidence`}><header><b>{symbol}</b><span className={quote?.stale?"stale":"fresh"}>{quote?.state.replaceAll("_"," ").toUpperCase()??"NOT AVAILABLE"}</span></header><strong>{quoteMoney(quote?.value,quote?.quoteCurrency)}</strong><dl><div><dt>TRADE / EVALUATION</dt><dd>{state}</dd></div><div><dt>LAST ACCEPTED EVALUATION</dt><dd>{asOfLabel(signal?.lastSuccessfulEvaluationAt)}</dd></div><div><dt>OBSERVATION</dt><dd>{asOfLabel(quote?.eventAt)} · {ageLabel(quote?.providerAgeSeconds??null)}</dd></div><div><dt>FETCH / PERSIST</dt><dd>{asOfLabel(quote?.receivedAt)} · last success {asOfLabel(quote?.lastSuccessAt)}</dd></div><div><dt>CURRENCY</dt><dd>{quote?.quoteCurrency??"UNVERIFIED"}</dd></div><div><dt>SESSION</dt><dd>{market?`${market.instrumentClass.toUpperCase()} · ${market.marketSession.toUpperCase()}`:"UNVERIFIED"}</dd></div><div><dt>POINTER</dt><dd>observation {quote?.observationId??"—"} · refresh run {quote?.refreshRunId??"—"}</dd></div></dl>{signal&&<p>{signal.gradingReason}</p>}<small>{quote?.trace??"No provider → persisted mark → API pointer is available."}</small></button>})}</div>
  <small className="daily-limit">Displayed source version proves this client bundle contains the repair. Deployment/build ID and source commit are not exposed to artifact actions; those remain pending platform evidence. Refresh coverage is the persisted inventory below, not a scheduler inference.</small>
 </section>;
}

type OpportunityStage = "discovery candidate" | "watch alert" | "confirmed paper entry";
type DeliveryBadge = "QUEUED" | "CHANNEL-ACKNOWLEDGED" | "FAILED" | "UNKNOWN";
type OpportunityUpdate = { key:string; stage:OpportunityStage; method:string; whyNow:string; observedAt:string|null; sourceUrl:string|null };
type Opportunity = {
  key: string; symbol: string; name: string; direction: "long" | "short" | null;
  stage: OpportunityStage; method: string; whyNow: string;
  observedAt: string | null; entryCondition: string | null; invalidation: string | null;
  historyCount: number; sourceUrl: string | null; dedupKey: string | null;
  updates: OpportunityUpdate[];
};
const slugKind = (kind: string) => kind.toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_|_$/g, "");
function directionFromText(text: string): "long" | "short" | null {
  const m = text.match(/\b(long|short)\b/i); return m ? (m[1]!.toLowerCase() as "long" | "short") : null;
}
function invalidationFromText(text: string): string | null {
  const m = text.match(/\binv(?:alidation)?\.?\s*\$?([\d,]+\.?\d*)/i); return m ? m[1]! : null;
}
const opportunityStageRank:Record<OpportunityStage,number>={"discovery candidate":1,"watch alert":2,"confirmed paper entry":3};
type EquityBoardData=ApiResponse<typeof api,"getEquityOpportunityBoard">;
type EquityBoardRow=EquityBoardData["rows"][number];
function EquityBoard({choose,openTape}:{choose:(q:string)=>void;openTape:(q:string)=>void}){
 const q=useQuery({queryKey:["equity-opportunity-board"],queryFn:()=>readWithDeadline(()=>api.getEquityOpportunityBoard({}),"Equity opportunity board read"),staleTime:60*1000,retry:false});
 const data=q.data;
 const openTracker=(row:EquityBoardRow,signalId:number)=>{openTape(row.symbol);scrollToId(`tracker-signal-${signalId}`);};
 return <section className="equity-board" aria-label="Equity opportunity board">
  <div className="section-head"><h3>Equity opportunity board</h3>{data?.run&&<span className="eyebrow">SCAN RUN #{data.run.id} · {data.run.universe.toUpperCase()} · DATA THROUGH SESSION {data.run.dataThroughSession??"UNAVAILABLE"}</span>}</div>
  {q.isPending?<LoadingSkeleton label="Loading equity opportunity board"/>:q.error?<div className="error" role="alert"><b>EQUITY BOARD READ FAILED</b><p>A failed read is not an empty board.</p><span>{shortError(q.error)}</span><div className="form-actions"><button className="secondary" onClick={()=>{void q.refetch()}}>RETRY READ</button></div></div>:data&&<>
   {data.partial&&<div className="board-partial" role="alert"><b>BOARD REBUILDING / PARTIAL</b><span>{data.partialNote}</span></div>}
   <div className="board-stamps"><span><small>VOL REGIME · CBOE</small><b>{data.volRegime.summary}</b></span><span><small>POSITIONING · CFTC COT</small><b>{data.cot.summary}</b></span><span><small>BOARD READ</small><b>{asOfLabel(data.generatedAt)}{data.latestRun?` · latest scan run #${data.latestRun.id} ${data.latestRun.status.toUpperCase()}`:""}</b></span></div>
   {data.rows.length?<div className="board-grid">{data.rows.map(row=><article key={row.symbol} id={`board-row-${row.symbol}`} className={`board-card${row.stale?" is-stale":""}`}>
    <header className="board-card-head"><div className="board-id"><b>{row.symbol}</b><small className="board-status-text">{row.name} · {row.sector}</small></div><div className="board-head-tags"><PopulationChip kind="issued"/>{row.trackedSignalProvenance.filter(p=>p.provenanceIncomplete).map(p=><span key={p.signalId} className="pop-chip provenance">PROVENANCE-INCOMPLETE · TRACKER #{p.signalId}</span>)}{row.stale&&<span className="stale-flag">STALE</span>}<strong className={row.direction==="long"?"pos":"neg"}>{row.direction.toUpperCase()} {row.score>0?"+":""}{row.score}</strong></div></header>
    <div className="board-facts">
     <div><span>QUOTE</span><strong>{row.quote.price==null?"PRICE UNKNOWN FROM THESE READS":num(row.quote.price,4)}</strong><small>Quote time: {row.quote.eventAt?asOfLabel(row.quote.eventAt):"not available in these reads"} · state {row.quote.state.replaceAll("_"," ")}</small></div>
     <div><span>COMPLETED-SESSION CHART READ</span><strong>{row.chartRead.direction.toUpperCase()} {row.chartRead.score>0?"+":""}{row.chartRead.score} · {row.chartRead.source}</strong><small>Completed session date: {row.completedSession.date??"unavailable from these reads"} · completed candle close {row.completedSession.close==null?"—":num(row.completedSession.close,4)} · candle event {row.completedSession.eventAt?asOfLabel(row.completedSession.eventAt):"unavailable"}</small></div>
     <div><span>SECTOR / INDEX CONTEXT</span><strong>{row.sectorContext}</strong></div>
     <div><span>BUSINESS EVIDENCE · SEC EDGAR</span><strong>{row.businessEvidence.present?`Present · ${row.businessEvidence.count} item${row.businessEvidence.count===1?"":"s"} · latest filing ${row.businessEvidence.form??"form unavailable"} filed ${row.businessEvidence.filedDate??"date unavailable"}`:"No stored business evidence for this dossier"}</strong>{row.businessEvidence.source&&<small>{row.businessEvidence.source}</small>}</div>
     <div><span>HORIZON</span><strong>{row.horizonLine}</strong></div>
     <div><span>NEXT CHECK</span><strong>{row.nextCheckLine}</strong></div>
    </div>
    {row.stale&&<p className="board-stale-line">STALE — {row.staleReasons.join(" · ")}. The stored values above keep their own event times; nothing stale is presented as current.</p>}
    {row.conflict&&<p className="board-conflict">{row.conflict}</p>}
    {row.noData.map(entry=><NoDataNote key={`${entry.metric}-${entry.classification}`} entry={entry}/>)}
    <div className="form-actions"><button className="secondary" onClick={()=>choose(row.symbol)} aria-label={`Open ${row.symbol} dossier`}>OPEN DOSSIER</button><button className="secondary" onClick={()=>openTape(row.symbol)} aria-label={`Open ${row.symbol} signal tape`}>SIGNAL TAPE</button>{row.trackedSignalIds.map(id=><button key={id} className="secondary" onClick={()=>openTracker(row,id)} aria-label={`Open tracker row for signal ${id}`}>TRACKER #{id}</button>)}</div>
   </article>)}</div>:<div className="empty"><b>{data.partial?"Partial board — no completed run to show yet.":"No directional names in the latest completed scan run."}</b><span>{data.partial?"The partial state above is the board state; rows appear when a scan run completes.":"Run a scan to rebuild the board from stored data."}</span></div>}
  </>}
 </section>;
}
type NotificationRowT = ApiResponse<typeof api,"getNotifications">["notifications"][number];
function NotificationsSection(){
 const qc=useQueryClient();
 const q=useQuery({queryKey:["notifications"],queryFn:()=>readWithDeadline(()=>api.getNotifications({limit:100}),"Notifications read"),staleTime:30*1000,retry:false});
 const ack=useMutation({mutationFn:(args:{notificationId?:number;markAll?:boolean})=>api.ackNotification(args),onSuccess:()=>qc.invalidateQueries({queryKey:["notifications"]})});
 const rows=q.data?.notifications??[];
 const nowMs=Date.now();
 const isExpired=(n:NotificationRowT)=>n.eventType==="EXPIRED"||(n.expiresAt!=null&&Date.parse(n.expiresAt)<=nowMs);
 const expired=rows.filter(isExpired);
 const lifecycle=rows.filter(n=>!isExpired(n)&&n.class==="lifecycle");
 const actionable=rows.filter(n=>!isExpired(n)&&n.class==="opportunity");
 const unread=q.data?.unreadCount??0;
 const renderRow=(n:NotificationRowT,expiredRow=false)=><article key={n.id} className={`notif-row${n.readAt?"":" unread"}`}>
  <header><div><b>{n.symbol}</b><span className={`notif-type ${n.eventType.toLowerCase()}`}>{n.eventType.replaceAll("_"," ")}</span>{expiredRow&&<span className="notif-expired-stamp">EXPIRED</span>}</div>{n.readAt?<span className="notif-read-state">READ {asOfLabel(n.readAt)}</span>:<span className="notif-read-state unread">UNREAD</span>}</header>
  <p className="notif-title">{n.title}</p>
  {n.reasonLines.map((line,index)=><p key={index} className="notif-reason">{line}</p>)}
  {n.blockerReason&&<p className="notif-blocker"><b>BLOCKED — </b>{n.blockerReason}</p>}
  {n.disclosure&&<p className="notif-disclosure">{n.disclosure}</p>}
  <p className="notif-times">EVENT {asOfLabel(n.eventAt)} → STORED {asOfLabel(n.storedAt)}{n.chatSentAt?` · SENT TO CHAT ${asOfLabel(n.chatSentAt)}`:""} · {n.expiresAt?`EXPIRES ${asOfLabel(n.expiresAt)}`:"no expiry recorded"}{n.reviewDue?` · REVIEW DUE ${asOfLabel(n.reviewDue)}`:""}</p>
  {!n.readAt&&<div className="form-actions"><button className="secondary" aria-label={`Mark ${n.symbol} notification ${n.id} read`} onClick={()=>ack.mutate({notificationId:n.id})} disabled={ack.isPending}>MARK READ</button></div>}
 </article>;
 return <section className="notifications" aria-label="Notifications">
  <header><div><span className="eyebrow">NOTIFICATIONS · TERMINAL-FIRST</span><h2>Notifications</h2><p>Opportunities and lifecycle events as committed by the terminal. Read state changes only when you mark a row read here.</p></div><div className="notif-head-actions"><strong className={unread?"notif-unread-count":""}>{unread} UNREAD</strong><button className="secondary" aria-label="Mark all notifications read" onClick={()=>ack.mutate({markAll:true})} disabled={!unread||ack.isPending}>MARK ALL READ</button></div></header>
  {q.isPending?<LoadingSkeleton label="Loading notifications"/>:q.error&&!q.data?<div className="error" role="alert"><b>NOTIFICATIONS READ FAILED</b><p>A failed read is not an empty inbox.</p><div className="form-actions"><button className="secondary" onClick={()=>{void q.refetch()}}>RETRY READ</button></div></div>:rows.length?<div className="notif-groups">
   {actionable.length>0&&<div className="notif-group"><h3>ACTIONABLE NOW · {actionable.length}</h3>{actionable.map(n=>renderRow(n))}</div>}
   {lifecycle.length>0&&<div className="notif-group"><h3>LIFECYCLE · {lifecycle.length}</h3>{lifecycle.map(n=>renderRow(n))}</div>}
   {expired.length>0&&<details className="notif-group notif-expired"><summary>EXPIRED · {expired.length}</summary>{expired.map(n=>renderRow(n,true))}</details>}
  </div>:<div className="empty"><b>No notifications recorded yet.</b><span>New scan candidates, watch alerts, blocked opportunities and tracker verdicts will appear here as the terminal commits them.</span></div>}
 </section>;
}
function Opportunities({choose,openTape,openTab}:{choose:(q:string)=>void;openTape:(q:string)=>void;openTab:(tab:Tab)=>void}){
  const alertsQ=useQuery({queryKey:["alerts"],queryFn:()=>readWithDeadline(()=>api.listAlerts({}),"Alert feed read"),staleTime:60*1000,retry:false});
  const scanQ=useQuery({queryKey:["auto-scan"],queryFn:()=>readWithDeadline(()=>api.getAutoScan({}),"Discovery read"),staleTime:60*1000,retry:false});
  const laneQ=useQuery({queryKey:["discovery-lane"],queryFn:()=>readWithDeadline(()=>api.getDiscoveryLane({}),"Discovery lane read"),staleTime:5*60*1000,retry:false});
  const deliveryQ=useQuery({queryKey:["alert-delivery-states"],queryFn:()=>api.getAlertDeliveryStates({}),staleTime:30*1000,retry:false});
  const deliveryByKey=new Map((deliveryQ.data?.states??[]).map(s=>[s.dedupKey,s]));
  const opportunities=useMemo(()=>{
    const raw: Opportunity[] = [];
    const byEvent=new Map<string,{latest:{id:number;symbol:string;kind:string;message:string;sourceUrl:string|null;createdAt:string};count:number}>();
    for(const a of alertsQ.data?.alerts??[]){
      const key=`${a.symbol}/${slugKind(a.kind)}`;
      const prior=byEvent.get(key);
      if(!prior||a.id>prior.latest.id) byEvent.set(key,{latest:a,count:(prior?.count??0)+1});
      else prior.count++;
    }
    for(const [key,group] of byEvent){
      const a=group.latest;
      if(isStale(a.createdAt)) continue;
      raw.push({key:`alert:${key}`,symbol:a.symbol,name:a.symbol,direction:directionFromText(`${a.kind} ${a.message}`),stage:"watch alert",method:a.kind,whyNow:a.message,observedAt:a.createdAt,entryCondition:a.kind.toLowerCase().includes("entry")?a.message:null,invalidation:invalidationFromText(a.message),historyCount:group.count-1,sourceUrl:a.sourceUrl,dedupKey:key,updates:[]});
    }
    for(const c of scanQ.data?.signals??[]){
      if(isStale(c.sourceAsOf)) continue;
      raw.push({key:`candidate:${c.id}`,symbol:c.symbol,name:c.name,direction:c.direction==="mixed"?null:c.direction,stage:"discovery candidate",method:"Automated discovery · five-dimension gate",whyNow:c.why,observedAt:c.sourceAsOf,entryCondition:null,invalidation:c.invalidationLevel!=null?String(c.invalidationLevel):null,historyCount:0,sourceUrl:c.sourceUrl,dedupKey:null,updates:[]});
    }
    for(const row of laneQ.data?.t2??[]){
      if(isStale(row.observedAt)) continue;
      raw.push({key:`lane:${row.symbol}`,symbol:row.symbol,name:row.instrumentName,direction:null,stage:"discovery candidate",method:`Discovery lane ${laneQ.data?.run?.laneVersion??""} · ${row.segment==="broad"?"broad universe":"small-cap list"}`,whyNow:row.reason,observedAt:row.observedAt,entryCondition:null,invalidation:null,historyCount:0,sourceUrl:null,dedupKey:null,updates:[]});
    }
    // One card per ticker. The highest-stage record becomes the card lead and
    // every other record remains visible in Updates, so dedup never drops data.
    const bySymbol=new Map<string,Opportunity[]>();
    for(const item of raw){const symbol=item.symbol.toUpperCase();bySymbol.set(symbol,[...(bySymbol.get(symbol)??[]),item]);}
    return [...bySymbol.values()].map(items=>{
      items.sort((a,b)=>opportunityStageRank[b.stage]-opportunityStageRank[a.stage]||(Date.parse(b.observedAt??"")||0)-(Date.parse(a.observedAt??"")||0));
      const [lead,...rest]=items;
      if(!lead) return null;
      return {...lead,historyCount:items.reduce((sum,item)=>sum+item.historyCount,0),updates:rest.map(item=>({key:item.key,stage:item.stage,method:item.method,whyNow:item.whyNow,observedAt:item.observedAt,sourceUrl:item.sourceUrl}))};
    }).filter((item):item is Opportunity=>item!==null).sort((a,b)=>opportunityStageRank[b.stage]-opportunityStageRank[a.stage]||(Date.parse(b.observedAt??"")||0)-(Date.parse(a.observedAt??"")||0));
  },[alertsQ.data,scanQ.data,laneQ.data]);
  const contextSymbols=useMemo(()=>opportunities.slice(0,25).map(item=>item.symbol),[opportunities]);
  const contextsQ=useQuery({queryKey:["opportunity-asset-contexts",contextSymbols.join("|")],queryFn:()=>api.getAssetContexts({symbols:contextSymbols}),enabled:contextSymbols.length>0,staleTime:60*1000,retry:false});
  const contextBySymbol=new Map((contextsQ.data?.contexts??[]).map(context=>[context.symbol,context]));
  const failed=alertsQ.error&&!alertsQ.data||scanQ.error&&!scanQ.data;
  const loading=alertsQ.isPending&&!alertsQ.data||scanQ.isPending&&!scanQ.data;
  const badgeFor=(opp:Opportunity):{badge:DeliveryBadge;detail:string|null}=>{
    if(!opp.dedupKey) return {badge:"UNKNOWN",detail:"No outbox row · homepage visibility is not chat delivery."};
    const s=deliveryByKey.get(opp.dedupKey);
    if(!s) return {badge:"UNKNOWN",detail:"No outbox row · homepage visibility is not chat delivery."};
    if(s.state==="delivered"&&s.deliveredAt) return {badge:"CHANNEL-ACKNOWLEDGED",detail:`Acknowledged ${asOfLabel(s.deliveredAt)}`};
    if(s.state==="failed") return {badge:"FAILED",detail:s.error??"Delivery failed without a recorded error."};
    if(s.state==="queued") return {badge:"QUEUED",detail:`Enqueued ${asOfLabel(s.enqueuedAt)}`};
    return {badge:"UNKNOWN",detail:s.state==="delivered"?"Outbox says delivered but has no acknowledgement timestamp.":"Outbox state is not recognized."};
  };
  return <section className="opportunities" aria-label="Current opportunities">
    <NotificationsSection/>
    <header><div><span className="eyebrow">OPPORTUNITIES · NEWEST FIRST</span><h1>What needs attention now</h1><p>One card per ticker. Watch alerts lead discovery candidates; related records stay visible under updates.</p></div><button className="secondary" onClick={()=>openTab("ALERTS")}>OPEN ALERT FEED</button></header>
    {loading?<LoadingSkeleton label="Loading opportunities"/>:failed?<div className="error" role="alert"><b>OPPORTUNITIES READ FAILED</b><p>A failed read is not an empty opportunity set.</p><div className="form-actions"><button className="secondary" onClick={()=>{void alertsQ.refetch();void scanQ.refetch();void laneQ.refetch();void deliveryQ.refetch();}}>RETRY READ</button></div></div>:opportunities.length?<div className="opportunity-grid">{opportunities.map(opp=>{
      const {badge,detail}=badgeFor(opp); const normalized=opp.symbol.toUpperCase(); const assetContext=contextBySymbol.get(normalized)??contextBySymbol.get(`${normalized}-USD`);
      return <article key={opp.symbol} className="opportunity-card">
        <header><div><span className={`stage ${opp.stage.replaceAll(" ","-")}`}>{opp.stage.toUpperCase()}</span><b>{opp.symbol}</b><small>{opp.name}</small></div><strong className={opp.direction==="long"?"pos":opp.direction==="short"?"neg":""}>{opp.direction?opp.direction.toUpperCase():"—"}</strong></header>
        <div className="opportunity-body"><p className="opp-method">{opp.method}</p><p className="opp-why">{opp.whyNow}</p>
        <div className="opp-facts"><div><span>OBSERVED</span><strong>{asOfLabel(opp.observedAt)}</strong></div>{opp.entryCondition&&<div><span>ENTRY CONDITION</span><strong>{opp.entryCondition}</strong></div>}<div><span>INVALIDATION</span><strong>{opp.invalidation??"not stated"}</strong></div><div><span>DELIVERY</span><strong className={`delivery-badge ${badge.toLowerCase()}`}>{badge}</strong>{detail&&<small>{detail}</small>}</div></div>
        {assetContext?<AssetContextView data={assetContext} compact/>:contextsQ.isPending?<small className="context-loading">Loading shared asset context…</small>:<small className="context-loading">Shared asset context unavailable.</small>}
        {(opp.updates.length>0||opp.historyCount>0)&&<details className="opp-updates"><summary>HISTORY / UPDATES · {opp.updates.length+opp.historyCount}</summary><div>{opp.updates.map(update=><article key={update.key}><header><span className={`stage ${update.stage.replaceAll(" ","-")}`}>{update.stage.toUpperCase()}</span><time>{asOfLabel(update.observedAt)}</time></header><b>{update.method}</b><p>{update.whyNow}</p>{update.sourceUrl&&<a href={update.sourceUrl} target="_blank" rel="noreferrer">SOURCE</a>}</article>)}{opp.historyCount>0&&<small>{opp.historyCount} earlier alert update{opp.historyCount===1?"":"s"} remain represented in the alert feed.</small>}</div></details>}
        <div className="form-actions"><button className="secondary" onClick={()=>choose(opp.symbol)}>OPEN DOSSIER</button><button className="secondary" onClick={()=>openTape(opp.symbol)}>SIGNAL TAPE</button>{opp.sourceUrl&&<a href={opp.sourceUrl} target="_blank" rel="noreferrer">SOURCE</a>}</div></div>
      </article>;
    })}</div>:<div className="empty"><b>No current opportunities.</b><span>No fresh alerts, qualifying candidates, or lane movers in the latest reads. A quiet board is shown as checked, not broken.</span></div>}
    <EquityBoard choose={choose} openTape={openTape}/>
  </section>;
}
function MarketLanding({choose,openTape,openTab,input,setInput,recent,loading}:{choose:(q:string)=>void;openTape:(q:string)=>void;openTab:(tab:Tab)=>void;input:string;setInput:(value:string)=>void;recent:string[];loading:boolean}){
 const [view,setView]=useState<"signals"|"trending">("signals");
 return <div className="market-landing">
  <div className="home-view-tabs" role="tablist" aria-label="Home view"><button role="tab" aria-selected={view==="signals"} className={view==="signals"?"active":""} onClick={()=>setView("signals")}><b>SIGNALS</b><span>Fast tracked calls</span></button><button role="tab" aria-selected={view==="trending"} className={view==="trending"?"active":""} onClick={()=>setView("trending")}><b>TRENDING</b><span>Runners · sectors · breadth</span></button></div>
  {view==="signals"?<><Opportunities choose={choose} openTape={openTape} openTab={openTab}/></>:<MarketHome choose={choose} openTab={openTab}/>}
  <HomePicker input={input} setInput={setInput} choose={choose} recent={recent} loading={loading}/>
 </div>;
}

function SignalLanding({openTape,openTab}:{openTape:(q:string)=>void;openTab:(tab:Tab)=>void}){
 const initialCache=useMemo(()=>readOpenSignalCache(),[]);
 const q=useQuery({queryKey:["open-signal-summary-bounded"],queryFn:loadOpenSignalSummary,staleTime:60*1000,initialData:initialCache??undefined,initialDataUpdatedAt:initialCache?0:undefined,retry:false});
 const freshness=useQuery({queryKey:["market-freshness-all"],queryFn:()=>api.getMarketFreshness({}),staleTime:60*1000,retry:false});
 const loaded=q.data; const data=loaded?.summary; const currentInput=(symbol:string)=>freshness.data?.symbols.find(row=>row.symbol===symbol)?.inputs.find(input=>input.kind==="quote");
 const activeSignals=(data?.signals??[]).filter(signal=>{const mark=currentInput(signal.symbol)?.value??signal.currentPrice;return markOutcome(signal.direction,mark,signal.invalidationLevel,signal.target1)==null;});
 return <section className="signal-landing" aria-label="Open tracked signals">
  <header><div><span className="eyebrow">LEGACY SIGNAL LEDGER · ACTIVE LEVEL MONITOR</span><h1>{data?`${activeSignals.length} genuinely open ${activeSignals.length===1?"signal":"signals"}`:"Tracked legacy signals"}</h1><p>Only calls whose latest mark remains between the frozen target and invalidation appear here. Level-closed calls move automatically to the full Signals logbook.</p></div><button className="secondary" onClick={()=>openTab("SIGNAL TAPE")}>OPEN FULL SIGNALS</button></header>
  {loaded&&<div className={`market-load-status ${loaded.source}`} role="status"><b>{loaded.source==="cached"?"CACHED SIGNAL LEDGER":"SIGNAL LEDGER UPDATED"}</b><span>{loaded.source==="cached"?`Saved ${asOfLabel(loaded.cachedAt)}`:`Read ${asOfLabel(data?.generatedAt)}`}</span>{loaded.fallbackReason&&<small>{loaded.fallbackReason}</small>}{q.isFetching&&<small>Checking for newer signal marks in the background…</small>}</div>}
  {q.isPending?<div className="signal-start"><span className="loading-dot"/><span><b>STARTING SIGNAL LEDGER…</b><small>Cold starts can take up to {timeoutSeconds(HOME_SIGNAL_TIMEOUT_MS)} seconds. The rest of the home stays usable.</small></span></div>:q.error?<div className="signal-load-failure"><div className="error">{shortError(q.error)}</div><details><summary>Technical details</summary><pre>{techDetail(q.error)}</pre></details><button className="action" onClick={()=>void q.refetch()}>RETRY SIGNALS</button></div>:data&&activeSignals.length?<div className="landing-signal-list">{activeSignals.map(signal=>{const live=currentInput(signal.symbol);const mark=live?.value??signal.currentPrice;const returnPct=mark==null?signal.returnPct:(signal.direction==="long"?(mark-signal.entryPrice)/signal.entryPrice:(signal.entryPrice-mark)/signal.entryPrice)*100;const evidenceCurrent=!!live&&!live.stale&&live.state==="fresh";const tradeLabel=evidenceCurrent?signal.tradeState.toUpperCase():"UNRESOLVED";const gradingLabel=evidenceCurrent?signal.gradingState.replaceAll("_"," ").toUpperCase():"EVIDENCE UNVERIFIED";return <button key={signal.id} onClick={()=>openTape(signal.symbol)} aria-label={`Open ${signal.symbol} signal tape`}><div className="landing-signal-id"><span className={`signal-direction ${signal.direction}`}>{signal.direction}</span><b>{signal.symbol}</b><small>{signal.name}</small></div><strong className={(returnPct??0)>=0?"pos":"neg"}>{returnPct==null?"NO MARK":pct(returnPct)}</strong><div className="landing-signal-levels"><span><small>ISSUED ENTRY</small>{quoteMoney(signal.entryPrice,live?.quoteCurrency)}</span><span><small>{live&&!live.stale&&live.state==="fresh"?"CURRENT MARK":"LAST KNOWN MARK"}</small>{quoteMoney(mark,live?.quoteCurrency)}</span><span><small>ISSUED INVALIDATION</small>{quoteMoney(signal.invalidationLevel,live?.quoteCurrency)}</span><span><small>ISSUED TARGET 1</small>{quoteMoney(signal.target1,live?.quoteCurrency)}</span></div><footer><span>{tradeLabel} {signal.daysOpen}D · {gradingLabel} · {dateLabel(signal.signalDate)} · LAST EVALUATION {asOfLabel(signal.lastSuccessfulEvaluationAt)}</span>{signal.provenanceIncomplete&&<PopulationChip kind="provenance"/>}<span className={!evidenceCurrent?"stale":"fresh"}>{live?`${live.state.replace("_"," ").toUpperCase()} · ${live.quoteCurrency??"CURRENCY UNVERIFIED"} · OBSERVATION ${ageLabel(live.providerAgeSeconds)} · EVENT ${asOfLabel(live.eventAt)} · FETCHED ${asOfLabel(live.receivedAt)} · LAST SUCCESS ${asOfLabel(live.lastSuccessAt)}${clockSkewLabel(live.eventAt,live.receivedAt)}`:`LEGACY MARK · ${isStale(signal.sourceAsOf)?"STALE":"CURRENT"} · EVENT ${asOfLabel(signal.sourceAsOf)} · OBSERVATION AGE ${ageLabel(ageFromIso(signal.sourceAsOf))} · FETCH TIME UNAVAILABLE`}</span></footer><small className="signal-grading-reason">{signal.gradingReason}</small></button>})}</div>:data?<div className="empty signal-landing-empty"><b>No level-open tracked signals.</b><span>Calls that reached a frozen target or invalidation are in the full Signals logbook.</span><button onClick={()=>openTab("SIGNAL TAPE")}>OPEN LOGBOOK</button></div>:null}
  {data?.latestBrief&&<div className="signal-ledger-brief"><b>PHASE 1.2 COHORT POST-MORTEM · {dateLabel(data.latestBrief.capturedDay)}</b><span>{data.latestBrief.summary}</span></div>}
  {data&&<small className="landing-asof">Ledger read {asOfLabel(data.generatedAt)} · display state recalculated from the latest persisted mark; no grading settlement was changed.</small>}
  <SchedulerEvidence/>
 </section>;
}

function SchedulerEvidence(){
 const run=useQuery({queryKey:["measurement-run-latest"],queryFn:()=>api.getLatestMeasurementRun({}),staleTime:60*1000,retry:false});
 const freshness=useQuery({queryKey:["market-freshness-all"],queryFn:()=>api.getMarketFreshness({}),staleTime:60*1000,retry:false});
 const scheduler=useQuery({queryKey:["scheduler-invocations"],queryFn:()=>api.getSchedulerInvocations({}),staleTime:30*1000,retry:false});
 const row=run.data;
 return <><ViewBanner view="diagnostics"/><details className="scheduler-evidence"><summary>SCHEDULER + GRADING EVIDENCE</summary><div className="scheduler-grid">
  <article><b>06:00 research goal</b><span>External research workflow · separate from this artifact</span><small>Its completion is not evidence that discovery, refresh, or grading ran here.</small></article>
  {scheduler.data?.jobs.map(job=><article key={job.jobKey}><b>{job.jobName}</b><span>{job.latest?`${job.latest.status.toUpperCase()} · ${asOfLabel(job.latest.invokedAt)}`:"NO SCHEDULED RECEIPT"}</span><small>{job.latest?`run ${job.latest.runId} · completed ${asOfLabel(job.latest.completedAt)}`:"No other job's run is used as evidence for this schedule."}</small></article>)??<article><b>Artifact-owned schedules</b><span>{scheduler.isPending?"LOADING RECEIPTS…":"RECEIPTS UNAVAILABLE"}</span><small>Each job is verified only by its own persisted invocation receipt.</small></article>}
  {row?<article><b>Last grading run ledger</b><span>{row.runId} · {row.status.toUpperCase()} · cutoff {asOfLabel(row.cutoffAt)}</span><small>frozen cohort {row.cohortKey} · expected {row.counts.inScope} · retrieved {row.counts.retrieved} · graded {row.counts.evaluated} · excluded {row.counts.excluded} · failed {row.counts.failed} · completed {asOfLabel(row.completedAt)}</small></article>:<article><b>Last grading run ledger</b><span>{run.isPending?"Loading run ledger…":"NO COMPLETED RUN LEDGER"}</span><small>No complete production grading claim is made without a persisted run ID and counts.</small></article>}
 </div><details className="refresh-inventory"><summary>EXPECTED REFRESH INVENTORY · {freshness.data?.symbols.length??0}</summary><div>{freshness.data?.symbols.map(symbol=>{const input=symbol.inputs.find(item=>item.kind==="quote");return <div key={symbol.symbol}><b>{symbol.symbol}</b><span>{input?.state.replaceAll("_"," ").toUpperCase()??"NOT ATTEMPTED"}</span><small>last attempt {asOfLabel(input?.lastAttemptAt)} · last success {asOfLabel(input?.lastSuccessAt)} · provider event {asOfLabel(input?.eventAt)} · pointer {input?.observationId??"none"} · next eligible {asOfLabel(input?.nextEligibleAt)} · {input?.error??"no recorded error"}</small></div>})}</div></details></details></>;
}

function HomePicker({input,setInput,choose,recent,loading}:{input:string;setInput:(value:string)=>void;choose:(value:string)=>void;recent:string[];loading:boolean}){
 return <section className="home-picker" aria-label="Analyze an asset"><div><span className="eyebrow">START A DOSSIER</span><h2>What do you want to understand?</h2></div><InstrumentAutocomplete input={input} setInput={setInput} choose={choose} loading={loading} home/><div className="home-recents"><b>RECENT PICKS</b>{recent.length?<div>{recent.map(item=><button key={item} onClick={()=>choose(item)}>{item}</button>)}</div>:<span>Your analyzed names will stay here on this device.</span>}</div></section>
}

type CrowdSearch = ApiResponse<typeof api,"searchCrowdMarkets">;
type CrowdOption = CrowdSearch["options"][number];
function Crowd(){
 const [input,setInput]=useState(""); const [query,setQuery]=useState(""); const [selected,setSelected]=useState<CrowdOption|null>(null);
 const search=useQuery({queryKey:["crowd-search",query],queryFn:()=>api.searchCrowdMarkets({query}),enabled:query.length>=2,staleTime:15*60*1000});
 const research=useMutation({mutationFn:(market:CrowdOption)=>api.researchCrowdMarket({query,slug:market.slug})});
 const submit=(event:FormEvent)=>{event.preventDefault();const next=input.trim();if(next.length<2)return;setSelected(null);research.reset();setQuery(next)};
 const select=(market:CrowdOption)=>{setSelected(market);research.mutate(market)}; const result=research.data;
 return <section className="crowd-page"><header><span className="eyebrow">POLYMARKET</span><h1>Crowd price vs measured base rate</h1><p>Search in plain words, pick the exact market, then compare its Yes price with a horizon-matched historical read.</p></header><form className="crowd-search" onSubmit={submit}><input aria-label="Search Polymarket markets" value={input} onChange={event=>setInput(event.target.value)} placeholder="BTC 90000 in 4 days"/><button disabled={input.trim().length<2||search.isFetching}>{search.isFetching?"SEARCHING…":"SEARCH"}</button></form>
  {search.error&&<div className="error">Market search failed: {shortError(search.error)}</div>}{search.data?.state==="no_data"&&<div className="empty">{search.data.reason}</div>}
  {search.data?.options.length?<div className="crowd-options" aria-label="Matching Polymarket options"><div className="section-head"><h3>SELECT A MARKET</h3><span>{search.data.options.length} MATCHES · {asOfLabel(search.data.asOf)}</span></div>{search.data.options.map(option=><button key={option.slug} className={selected?.slug===option.slug?"active":""} onClick={()=>select(option)}><span><b>{option.question}</b>{option.eventTitle&&option.eventTitle!==option.question?<small>{option.eventTitle}</small>:null}</span><strong>{num(option.yesImpliedCrowdPrice*100,1)}% YES<small>{money(option.volume24hr)} 24H VOL</small></strong></button>)}</div>:null}
  {research.isPending&&<LoadingSkeleton label="Researching selected market"/>}{research.error&&<div className="error">Research failed: {shortError(research.error)}</div>}{result&&<article className={`crowd-verdict ${result.state}`}><div className="section-head"><h3>RESEARCHED VERDICT</h3><span>{result.state==="available"?"MEASURED":"PROBABILITY WITHHELD"}</span></div><h2>{result.market?.question}</h2><div className="crowd-comparison"><div><small>CROWD IMPLIED</small><b>{result.crowdProbability==null?"—":`${num(result.crowdProbability,1)}%`}</b><span>Polymarket Yes price · {result.market?asOfLabel(result.market.asOf):"timestamp unavailable"}</span></div><div><small>TERMINAL READ</small><b>{result.researchedProbability==null?"WITHHELD":`${num(result.researchedProbability,1)}%`}</b><span>{result.researchedProbability==null?result.reason:`Empirical base rate · N=${result.sampleSize}`}</span></div><div><small>POTENTIAL EDGE</small><b className={(result.edgePoints??0)>0?"pos":(result.edgePoints??0)<0?"neg":""}>{result.edgePoints==null?"—":`${result.edgePoints>0?"+":""}${num(result.edgePoints,1)} pts`}</b><span>Terminal minus crowd · not a trade signal</span></div></div><div className="crowd-basis"><b>BASIS</b><p>{result.basis}</p>{result.factorAgreement&&<span>Current factor agreement {result.factorAgreement.score>0?"+":""}{result.factorAgreement.score} · {result.factorAgreement.direction} · comparison band {result.factorAgreement.band}{result.instrument?` · ${result.instrument.symbol} ${money(result.instrument.price)}`:""}</span>}</div>{result.market&&<a className="secondary crowd-source" href={result.market.marketUrl} target="_blank" rel="noreferrer">OPEN SELECTED MARKET</a>}</article>}
 </section>
}

function InstrumentPrompt({onFocus}:{onFocus:()=>void}){return <div className="instrument-prompt"><span className="eyebrow">INSTRUMENT VIEW</span><h2>Choose what to analyze.</h2><p>Search a ticker, company, private company, or commodity above to open its dossier and market evidence.</p><button className="action" onClick={onFocus}>SEARCH INSTRUMENTS</button></div>}

type StockValuation = ApiResponse<typeof api,"valuestock">;
function ValuationBlock({symbol,initialData}:{symbol:string;initialData:StockValuation|null}){
 const run=useMutation({mutationFn:()=>api.valuestock({symbol})});
 const data=run.data??initialData;
 return <section className="valuation-block" aria-label={`${symbol} equity valuation`}>
  <header className="valuation-head"><div><h2>Equity valuation</h2><p>Loaded with the dossier. Cash flows, dilution, multiples and operating evidence; no price target.</p></div><button className="action" onClick={()=>run.mutate()} disabled={run.isPending}>{run.isPending?"REFRESHING…":"REFRESH"}</button></header>
  {!data&&!run.isPending&&!run.error&&<div className="valuation-empty"><b>VALUATION UNAVAILABLE</b><span>The free fundamentals layer returned no usable result.</span></div>}
  {run.isPending&&<LoadingSkeleton label={`Refreshing ${symbol} valuation`}/>} {run.error&&<div className="error">Valuation refresh failed: {shortError(run.error)}</div>}
  {data&&<ValuationResult data={data}/>} 
 </section>
}
function ValuationResult({data}:{data:StockValuation}){
 const sourceById=new Map(data.sources.map(source=>[source.id,source]));
 const sourceLinks=(ids:string[])=><span className="valuation-cites">{ids.map(id=>{const source=sourceById.get(id);if(!source)return null;return source.url?<a key={id} href={source.url} target="_blank" rel="noreferrer">{id}</a>:<span key={id}>{id}</span>})}</span>;
 return <div className="valuation-result">
  <div className="valuation-status"><span className={`status ${data.status==="ok"?"confirming":data.status==="partial"?"contested":"challenged"}`}>{data.status}</span><b>{data.symbol} · as of {asOfLabel(data.asOf)}</b><span>{data.note}</span></div>
  {data.refresh.state!=="not_needed"&&<div className={`valuation-refresh ${data.refresh.state}`}><b>KEYED CROSS-CHECK · {data.refresh.state.toUpperCase()}</b><span>{data.refresh.note}</span></div>}
  <div className="valuation-sections">{data.sections.map(section=><details key={section.number} className="valuation-section" open={section.number===1||section.number===4||section.number===8}><summary><span>{String(section.number).padStart(2,"0")}</span><b>{section.title}</b><em className={section.verdict==="cheap"||section.verdict==="supportive"?"pos":section.verdict==="rich"||section.verdict==="caution"?"neg":""}>{section.verdict}</em></summary><div className="valuation-section-body"><p>{section.summary}</p>{section.metrics.length>0&&<div className="valuation-metrics">{section.metrics.map(metric=><div className={`valuation-metric ${metric.status}`} key={metric.label}><small>{metric.label}</small><strong>{metric.value}</strong><span>{metric.detail} {sourceLinks(metric.sourceIds)}</span></div>)}</div>}{section.evidence.length>0&&<ul className="valuation-evidence">{section.evidence.map((item,index)=><li key={index}>{item.text} {sourceLinks(item.sourceIds)}</li>)}</ul>}</div></details>)}</div>
  <details className="valuation-method"><summary>Method + sources</summary><div><ul>{data.assumptions.map(item=><li key={item}>{item}</li>)}</ul><ol>{data.sources.map(source=><li key={source.id}><b>{source.id}</b> · {source.url?<a href={source.url} target="_blank" rel="noreferrer">{source.label}</a>:source.label} · as of {source.asOf}</li>)}</ol></div></details>
 </div>
}

type AssetContextData=ApiResponse<typeof api,"getAssetContext">;
function AssetContextView({data,compact=false}:{data:AssetContextData;compact?:boolean}){
 const sourceById=new Map(data.sources.map(source=>[source.id,source]));
 const answers=Object.values(data.answers);
 const body=<><div className="asset-context-answers">{answers.map((answer,index)=>{const displayText=compact&&answer.text.length>180?`${answer.text.slice(0,177).trim()}…`:answer.text;return <article key={answer.label}><span>{index+1}</span><div><small>{answer.label}</small><p>{displayText}</p><footer>{answer.asOf?`As of ${asOfLabel(answer.asOf)}`:"Date unavailable"}{answer.sourceIds.map(id=>{const source=sourceById.get(id);if(!source)return null;return source.url?<a key={id} href={source.url} target="_blank" rel="noreferrer">[{id}]</a>:<b key={id}>[{id}]</b>})}</footer></div></article>})}</div><div className="asset-context-market"><div><small>STORED PRICE</small><b>{money(data.market.price)}</b><span>{asOfLabel(data.market.priceAsOf)}</span></div><div><small>SIGNAL</small><b>{data.market.signalStatus}</b><span>{asOfLabel(data.market.signalAsOf)}</span></div><div><small>DELIVERY</small><b className={`delivery-badge ${data.market.deliveryStatus}`}>{data.market.deliveryStatus.replace("_"," ").toUpperCase()}</b><span>{asOfLabel(data.market.deliveryAsOf)}</span></div></div><div className="asset-context-ledgers"><details><summary>SOURCES · {data.sources.length}</summary><div>{data.sources.map(source=><p key={source.id}><b>[{source.id}]</b> {source.url?<a href={source.url} target="_blank" rel="noreferrer">{source.title}</a>:source.title}<span>{source.evidenceClass.replaceAll("_"," ")} · {source.kind} · {source.stance} · {asOfLabel(source.observedAt)}</span></p>)}</div></details><details><summary>CALCULATIONS · {data.calculations.length}</summary>{data.calculations.length?data.calculations.map(item=><p key={item.label}><b>{item.label}</b><span>{item.expression}</span></p>):<p>No stored signal calculation is available.</p>}</details><details><summary>ASSESSMENT HISTORY · {data.history.length}</summary>{data.history.length?data.history.map(item=><p key={item.id}><b>{item.kind.toUpperCase()} · {asOfLabel(item.assessedAt)}</b><span>{item.explanation} · {item.evidenceCount} evidence item{item.evidenceCount===1?"":"s"}</span>{item.outcomes.map((outcome,index)=><em key={index}>{outcome.status.toUpperCase()} · {outcome.summary} · {asOfLabel(outcome.observedAt)}</em>)}</p>):<p>No assessment snapshot exists yet.</p>}</details></div>{data.gaps.length>0&&<p className="asset-context-gaps">GAPS · {data.gaps.join(" · ")}</p>}<small className="asset-context-note">{data.note}</small></>;
 if(compact)return <details className="asset-context compact"><summary>ASSET CONTEXT · FIVE QUESTIONS</summary>{body}</details>;
 return <section className="asset-context" aria-label={`${data.symbol} asset context`}><header><div><span className="eyebrow">SHARED ASSET CONTEXT · {data.profileStatus.toUpperCase()}</span><h2>{data.symbol} in five questions</h2></div><span>Retrieved {asOfLabel(data.contextRetrievedAt)}</span></header>{body}</section>;
}
function AssetContextPanel({symbol}:{symbol:string}){const q=useQuery({queryKey:["asset-context",symbol],queryFn:()=>api.getAssetContext({symbol}),staleTime:60*1000});if(q.isPending)return <LoadingSkeleton label={`Loading ${symbol} asset context`}/>;if(q.error)return <section className="asset-context"><div className="error">Asset context unavailable: {shortError(q.error)}</div><details><summary>Technical details</summary><pre>{techDetail(q.error)}</pre></details><button className="secondary" onClick={()=>void q.refetch()}>RETRY CONTEXT</button></section>;return q.data?<AssetContextView data={q.data}/>:null;}

function DossierSynthesis({a}:{a:Analysis}){
 const synthesis=a.synthesis,sections=a.sectionVerdicts;if(!synthesis||!sections)return null;
 const rows=[{label:"CHART",...sections.chart},{label:"VALUATION",...sections.valuation},{label:"SMART MONEY",...sections.smartMoney},{label:"POSITIONING",...sections.crowd}];
 return <section className={`dossier-synthesis ${synthesis.verdict}`} aria-label="Dossier cross-synthesis"><header><div><span className="eyebrow">CROSS-SYNTHESIS</span><h2>{synthesis.verdict.replace("_"," ").toUpperCase()}</h2></div><span>Analysis generated at {asOfLabel(a.delivery.generatedAt)} · {a.delivery.cacheHit?"cached daily dossier":"new dossier analysis"} · {num(a.delivery.durationMs,0)} MS</span></header><p className="synthesis-conclusion">{synthesis.conclusion}</p><div className="synthesis-grid">{rows.map(row=><article key={row.label}><small>{row.label}</small><b>{row.verdict.toUpperCase()}</b><p>{row.interpretedLine}</p><span>{row.supportingFigures.join(" · ")}</span></article>)}</div><div className="synthesis-invalidation"><b>WHAT INVALIDATES THE CALL</b><p>{synthesis.invalidation}</p></div></section>;
}

function MiniSpark({values,tone="neutral"}:{values:number[];tone?:"positive"|"negative"|"neutral"}){
 const rows=values.map((value,index)=>({index,value}));
 if(rows.length<2)return <span className="spark-empty">CHART UNAVAILABLE</span>;
 return <div className={`mini-spark ${tone}`} aria-hidden="true"><ResponsiveContainer width="100%" height="100%"><ComposedChart data={rows} margin={{top:3,right:2,bottom:3,left:2}}><Area type="monotone" dataKey="value" stroke="currentColor" fill="currentColor" fillOpacity={0.12} strokeWidth={2} isAnimationActive={false}/></ComposedChart></ResponsiveContainer></div>;
}
